# ===== 2026-11-04 v3：内容形态分类 → 重要度 =====
#
# 为什么不能用 tags：186 条里 115 条都标了「人设相关」，这个标签不携带信息。
# 实测把「迁移数据目录」和「晚安早点睡」判成同一类，所以改成看内容形态。
#
# 重要度只用于决定**衰减地板**（floor = importance × 60），不参与召回打分。
# 这样排序还是靠相关性（说法自然），但重要的事不会被时间磨没。

FACT_PATTERNS = [
    r"生日是", r"是 ?\d+ ?月",
    # 「在.{2,6}(区|市|省|县)」会把「在工作区外」误当成地址：后缀紧跟方位词则排除。
    r"在.{2,6}[区市省县](?![外里内边侧上下])",
    r"ID ?\d{6,}",
    # 「住」必须独立成词——前面不能是动词字（含/停/抓/抱/忍/撑/接/拦），
    # 后面必须是「在/于/的/过」或直接跟地名（市区省县），例如「住在某市」「在某区」。
    r"(?:^|[，。；：、\s])(?:我|他|她|用户)?住(?:在|于|过|的)?[^，。；：\s]{1,10}(?:区|市|省|县|路|街|小区|号楼|室)",
    r"(?:我|他|她|用户)\s*住在[^，。；：\s]{1,10}",
    # 重大医疗事件由下方 CRITICAL_EVENT_PATTERNS 单列（判 event + 0.92）。
    r"\d{1,2}[:：点]\d{0,2}",
    # 规则句式才判 fact（「禁止/不许」+ 具体动作），不把日常口语否定词全当规则。
    r"(?:禁止|不许|不准)(?:碰|动|改|删|看|进|用|装|跑|关闭|修改|删除|打开|访问)",
    # 「不能 + 系统级对象」仍判规则（例如「不能修改 Program Files」）。
    r"不能(?:碰|动|改|删|用|装|跑|修改|删除|访问|关闭).{0,12}(?:Program|Windows|系统|盘|目录|权限|注册表|system32|C )",
    r"(?:必须|一定要)(?:先|提前|记|备份|问|确认|告诉|做|写|用)",
    r"(?:规矩|规定|原则|铁律)(?:是|就)",
    r"禁(?:止|用).{0,6}(?:系统|文件|盘|目录|权限)",
    r"告诉过我|明确说过",
    # ★ 2026-11-10 收紧（500 条真实对话逐条归因，6 条误判）：
    #
    #   原来是 r"先问|问他|要问他|问他同意|得先|得问"
    #   而「先问」和「得先」在中文里是**极度常见**的词组：
    #     「你都会先问。这一点我一直记着」   → 命中「先问」← 夸他，不是规则
    #     「现代我得先能养活自己」           → 命中「得先」← 人生规划
    #     「这个得先分清」                   → 命中「得先」← 技术讨论
    #     「我得先说」                       → 命中「得先」← 口语
    #     「那我得先问清楚」                 → 命中「得先」← 口语
    #   实测 6 条命中全是误判，0 条真规则。
    #
    #   修法：「问」必须是真的在问**许可**——
    #     ① 「先问我/先问他/先问过」这种**带对象**的
    #     ② 「得先/必须先 + 问/征得/得到 + 同意/许可/允许/批准」
    #   这样「必须先问我才能删」「得先问他同意」仍然命中，
    #       而「我得先说」「得先分清」「你都会先问」不再命中。
    r"先问(?:我|他|过)",
    r"(?:得|要|必须)先(?:问|征得|得到).{0,6}(?:同意|许可|允许|批准)",
    r"问(?:我|他)同意",
]

# 2026-11-06 短期记忆层：承诺/约定/日期 单独拎出来，命中直接进长期库 L3，不跟 3 天衰减走。
#
# 2026-11-07 修（实测发现的误判）：原来最后一组是
#     r"明天|后天|周末|下周|下次|以后|将来|哪天|到时候"
#   **光有时间词就算承诺**，结果这句被判成 commitment（0.92，最高档）：
#     「这是一个很长很长的吐槽今天真的好累啊明天还要早起真的受不了了…」
#   它只是在抱怨，根本没承诺任何事，却因为含「明天」被永久记住。
#
#   修法：时间词**单独不算承诺**，必须跟「承诺动作」一起出现才算。
#     ① 有承诺动词（答应/说好/约好/记住…）→ 不管有没有时间词，都是承诺
#     ② 只有时间词 → 不算承诺，让它走正常分类（多半会落 event / about_him）
#   这样「明天十点开会」仍然会被判成日期/事件进长期库（靠 DATE_PATTERNS），
#   但「明天还要早起好烦」不会再被当成承诺。
COMMITMENT_PATTERNS = [
    # ★ 2026-11-10 收紧（Codex 审查包 + 排查B 对比后，我做了折中设计）
    #
    #   原来的问题（实测 500 条对话）：
    #     r"约好|约定|说好|记住.*(我|你)|别忘了"
    #   只要句子里出现「约定」两个字就判承诺，于是：
    #     「不能所有东西都打重要约定」   → commitment 0.92  ❌
    #     「只是随便约定一下」           → commitment 0.92  ❌
    #     「这个约定不作数」             → commitment 0.92  ❌
    #     「按约定应该这样做」           → commitment 0.92  ❌
    #
    #   Codex 包的做法是要求「跟/和/与 + 约好」这种句式，但实测：
    #     真承诺 12 条里它漏了 10 条（"我答应你明天三点叫你" 都不命中）
    #     真实对话命中从 23 条塌到 1 条
    #   → 过度收紧，等于把承诺识别废掉。
    #
    #   我的折中（实测 12/12 真承诺 + 0/6 噪音 + 真实对话 9 条全真）：
    #     ① 强承诺动词保留（答应/保证/发誓/定下来）—— 这些几乎总是承诺
    #     ② 「约好/约定/说好」要求**动作句式**（有主语/后续内容）
    #     ③ 「记住/别忘」要求跟具体对象
    #     ④ 「永远/一辈子」要求人称语境
    #   配合下面的 COMMITMENT_EXCLUDE 排除名词性用法。
    r"我答应|答应过|答应你|答应他|答应我",
    r"我保证|保证(?:不再|以后|会|一定)",
    r"我发誓|发誓(?:不再|以后|会)",
    r"定下来了|就这么定了|说定了",
    # ★ 2026-11-10 二次收紧（排查B 用 500 条真实对话验出来的）
    #
    #   上一版这两条在干净样本上是 12/12 + 6/6，但在真实对话上：
    #     命中 9 条，只有 4 条是真承诺（精准率 44%）
    #
    #   误判根因（逐条看出来的）：
    #     「那我记着了，你说好看」   → 命中「说好」← 其实是「说好看」
    #     「你今天说好几遍了」       → 命中「说好」← 其实是「说好几遍」
    #     中文没有词边界，`说好` 会吃掉 `说好看`/`说好几遍`/`说好像`
    #     → 必须用**后面不能跟某些字**来排除
    #
    #     「但你一辈子都不愿意给我」 → 命中「一辈子」← 这是**拒绝**
    #     「谁都不用陪一辈子呀」     → 命中「一辈子」← 也是拒绝
    #     → 「永远/一辈子」单独出现几乎都不是承诺，
    #        必须跟具体承诺动作搭配（等/陪/记/爱/不离开）
    #
    #   「约好/说好」：要求后面不跟（看/几/像/的/笑/听/话），且必须跟承诺内容
    r"(?:我们|咱|跟你|和你|跟他|和我)?[^，。；：]{0,4}(?:约好|说好)(?![看几像的笑听话])了?[^，。；：]{1,12}",
    r"(?:约好|约定|说好)(?:下|周|月|天|要|会|去|一起|见面|出发)",
    r"(?:记住|别忘了|别忘记)[^，。；：]{1,12}",
    # 永远/一辈子：必须跟具体承诺动作搭配，不能单独出现
    #
    # ★ 2026-11-10 修正：「我会永远陪着你」被漏了。
    #   原写法 `(?:我|你)(?:会|一定|永远)(?:等|陪|…)` 要求第一层修饰词
    #   后面**直接**跟动作，而「会永远陪着」中间隔了「永远」两个字。
    #   改成允许中间插入 0-2 个修饰字。
    r"(?:我|你)(?:会|一定|永远)[^，。；：]{0,2}(?:等|陪|记|爱|在|护|守)",
    r"永远(?:不|别|不会)(?:离开|走|忘|变)",
    r"一辈子(?:都|也|会)?[^，。；：]{0,2}(?:不|会)(?:离开|走|忘|变)",
    r"一辈子(?:都|也)?会?(?:记得|记着|记住)",
    r"(?:答应|保证|发誓)(?:永远|一辈子)",
    # ★ 2026-11-16 补：「记着 / 记下了」这类口语约定。
    #
    #   实测（508 条短期层）漏掉的真实约定：
    #     「这个我记着。以后也记着」          ← 漏
    #     「以后固定走你调的那条」            ← 漏
    #   原词表只有「记住 / 别忘了 / 别忘记」，口语里更常用的是「记着」。
    #
    #   为什么要求「我记着」而不是裸的「记着」：
    #     他说的「你得记着」也算承诺，但她说的「我记着」更明确是承接。
    #     两种都收，但都要求前面有人称，避免「记着这个数」这种普通叮嘱
    #     在任意上下文里被误判。
    #
    #   为什么不加「行」「好」「听你的」这类纯口语答应：
    #     实测「他说：好；我回：嗯，那我趴一会儿」这种流水一天几十条，
    #     加了会把短期层一半判成承诺。只在她说出「记着/记下」这种
    #     带记忆意图的词时才认。
    r"(?:我|自己)(?:会|也|都)?(?:记着|记下了|记住了)(?![的不])",
    r"(?:以后|下次|往后)[^，。；：]{0,6}(?:都|也)?(?:记着|记下|走你|听你的|按你说的)",
    # ★ 2026-11-16 补（clever-willow 建议）：句末的「说好的」。
    #
    #   实测漏掉：「这事就这么定了。说好的」
    #   原 pattern 是
    #     (?:约好|说好)(?![看几像的笑听话])了?[^，。；：]{1,12}
    #   要求「说好」后面必须跟 1~12 个字，而「说好的」后面直接是句号
    #   → 匹配失败 → 判成 event 0.65。
    #
    #   为什么用后向断言 (?=[。！？，、\s]|$) 而不是把 {1,12} 改成 {0,12}：
    #     {0,12} 会让「这也是说好的事」这种名词性用法也命中（误伤）；
    #     后向断言要求「说好的」后面紧跟标点或字符串结束，
    #     含义是「说完这句就确认了这个约定」，名词性用法天然被排除。
    #   实测（2026-11-16）：
    #     ✅「这事就这么定了。说好的。」→ 命中
    #     ❌「这也是说好的事」              → 不命中
    r"说好的(?=[。！？，、\s]|$)",
    # 明确的提醒托付（「下周/明天/帮我提醒我做某事」），避免被归入普通 misc 而 3 天遗忘
    r"(?:明天|后天|下周|下星期|下个月|每周|每天|周[一二三四五六日天]|星期[一二三四五六日天]|明早|今晚|晚上|待会|一会儿|回头|到时候|帮我|麻烦|请|记得)[^，。；：？?]{0,8}提醒我[^，。；：？?]{1,20}",
    r"(?:^|[，。；：,\s])提醒我[^，。；：？?]{1,20}(?:明天|后天|下周|下星期|下个月|周[一二三四五六日天]|星期[一二三四五六日天]|明早|今晚|晚上|待会|一会儿)",
]

# ★ 2026-11-10 新增：commitment 的名词性用法排除。
#
#   为什么需要单独一个排除列表，而不是把正则写得更严：
#     中文没有词边界，「这个约定」和「我们约好」都含「约定/约好」，
#     用一条正则同时区分「名词用法」和「动作用法」会非常难写且易漏。
#     拆成「先匹配 + 再排除」两步，每条规则都短、都能单独验证。
COMMITMENT_EXCLUDE = [
    r"这个约定|那个约定|按约定|约定是|约定的|约定这|约定那",
    r"重要约定|打重要约定|所有东西都打",
    r"(?:不能|不该|不算|不作数|没用).{0,6}约定",
    # ★ 2026-11-10 二次收紧（500 条真实对话验出来的）：
    #
    #   反问句会被误判成承诺。实测：
    #     「你说哪样我没答应过呀」→ 命中「答应过」← 但这是反问，不是承诺
    #
    #   反问的特征：「哪样/哪儿/什么」+ 「没/不」+ 承诺动词
    r"(?:哪样|哪里|哪儿|什么|谁)(?:我)?(?:没|不)(?:答应|说过|保证)",
    # ★ 2026-11-10 补（排查B 扫描 29 条反问样本时抓到的第 29 条）：
    #
    #   「我什么时候没答应过」—— 上面那条要求「疑问词 + 我」，但这句是
    #   「我 + 什么时候 + 没 + 答应过」，顺序反了。
    #
    #   实测：真实对话里没出现过这条，影响极小。
    #   但既然发现了就补上 —— 反问误判成承诺会让它进 L3 活 32 天，
    #   代价不对等（补一条永久的成本 << 错一次的成本）。
    r"(?:我)?(?:什么|哪|几)时(?:候)?(?:没|不)(?:答应|保证|说过)",
    #   拒绝/否定语境：
    #     「你从来没让我必须听你的」
    #     「我保证不了」「答应不了」
    r"(?:答应|保证|发誓)(?:不了|不到|不下来)",
    r"(?:没|不|别)(?:答应|保证|发誓)(?!过)",
    r"(?:别|不要|不用|不必|没必要|千万别)提醒我",
    r"(?:怎么|为什么|啥时候|什么时候|有没有|能不能|可不可以|会不会)[^，。；：]{0,4}提醒我",
]

# 时间词（单独出现时**不**构成承诺，只作为「约定」的辅助信号）
TIME_HINT_PATTERNS = [
    r"明天|后天|周末|下周|下次|以后|将来|哪天|到时候",
]

# ★ 2026-11-10 新增：重大医疗/生命事件。
#
#   为什么单独一类（不是 fact，也不是普通 event）：
#     · 它**不是** fact  —— 「他家人住院了」不是恒久不变的事实，是一件事
#     · 但它**必须**有 fact 级的分量（0.92）—— 这种事要记一辈子
#
#   为什么现在要加：
#     原来靠 `住.{1,8}` 这个宽正则把「住院」捎带判成 fact 0.92。
#     我把那条收紧后（因为「含住」「抱住」被误判），「住院」也跟着掉到 0.55，
#     结果丢掉了 importance>=0.85 的保护线，cross_test R18 由绿变红。
#     所以这里把「重大医疗事件」显式接管：判 event，但 importance 0.92。
#
#   边界：只收**明确的医疗/生命危机**，不收「去医院」「看医生」这类日常就医。
CRITICAL_EVENT_PATTERNS = [
    r"住院|手术|急诊|抢救|化疗|放疗|ICU|重症|病危|开刀|住院部",
    r"确诊|癌|肿瘤|中风|心梗|脑梗|骨折|昏迷|输血|透析",
    r"去世|过世|走了(?!吧)|葬礼|病逝",
]

DATE_PATTERNS = [
    r"\d{1,2}月\d{1,2}[日号]", r"生日是|纪念日",
    # 2026-11-07 修：原来只认阿拉伯数字的「1:30 / 10点」，
    #   中文聊天里实际都是「十点」「三点」——实测「明天十点开会」判成了 misc。
    #
    #   但不能简单写成 [一二三四五六七八九十]+[点时]，实测会误判：
    #     「这一点很重要」「他一点都没变」「今天一点累」→ 全被判成 date(0.92)
    #   所以要求中文数字后面必须跟**明确的钟点语境**：
    #     ① 「N点」后面紧跟 开会/上课/见/到/走/睡/起/集合/出发/下课 等具体动作
    #     ② 或者「N点半 / N点整 / N点N分」这种明确时间格式
    # ★ 2026-11-12 修（实测：484 条里 155 条被判 date，占 32%）：
    #
    #   原来这里是 r"\d{1,2}[:：点]\d{0,2}" —— `\d{0,2}` 允许零位，
    #   于是「数字 + 冒号」全部命中：
    #
    #     「2026-10-26：数据整理完成」    → 匹配「26：」
    #     「2026-10-27：朋友确认了…」        → 匹配「27：」
    #     「11-08 12:45，做饭（2 轮）」       → 匹配「12:45」（这个是对的）
    #
    #   后果：**125 条 episode 全部被判 date(0.92)**，
    #   本该是 event(0.65)。等于所有情景档都拿到最高重要度，
    #   永远不掉出保护线。日记时间戳、目录编号也全都中招。
    #
    #   修法：冒号后必须跟分钟（1~2 位数字）。
    #     「26：」不匹配（后面是中文）✅
    #     「12:45」匹配 ✅          「8：30」匹配 ✅
    #   中文「点」的判定由下面几条独立负责，不靠这条兜。
    r"\d{1,2}[:：点]\d{1,2}",
    # ★ 2026-11-10 三次收紧（排查B 用 500 条真实对话逐条归因）：
    #
    #   原来的 \d 分支没有「分」的要求，于是：
    #     「（加快一点9签1深」→ 匹配「一」+「点」+「9」= 「一点9」
    #   实测这种误判有 2 条。
    #
    #   修法：\d 后面必须跟「分」才认（这是 \d 分支的本意：
    #         匹配「三点15分」的「15」，不是任意数字）。
    #   顺带补：允许「一点两点」这种连续两点的情况。
    #
    #   验证（9/9）：
    #     「三点15分见」✅命中    「一点9签1深」✅不命中
    #     「三点半」✅命中        「差一点」✅不命中
    #     「三点十五分」✅命中    「一点两点」✅命中
    #
    # ★ 2026-11-10 再修：「一点一点」被连续两点分支吃掉了。
    #   实测误判 2 条：
    #     「（含着一点一点往里，节奏稳了」  → date 0.92
    #     「含着那个深度一点一点动」        → date 0.92
    #   而「一点一点」是程度副词（=一点点），不是时间。
    #   修法：负向前瞻排除「X点X点」的**完全重复**形式；
    #        「一点两点」（不同数字）仍算时间，是真的可能表示时段。
    r"(?![一二三四五六七八九十两]\s*点\s*[一二三四五六七八九十两]\s*点)"
    r"[一二三四五六七八九十两]+\s*[点點]\s*"
    r"(?:半|整|\d+\s*分|[一二三四五六七八九十]+\s*分|"
    r"开会|上课|下课|见|到|走|睡|起|集合|出发|来|去|交|开始|结束)",
    r"周[一二三四五六日天]",
    # ★ 2026-11-10：从 `几号|几月|哪天|什么时候` 里移除「什么时候」。
    #
    #   为什么：「什么时候」是口语疑问句的高频词，实测 500 条里 2 次命中
    #   全是「你什么时候醒的」「你什么时候出来跟我说一声」——
    #   **没有一次是「要记住的日期」**。
    #
    #   而 date 类的本意是「要记住的日子」（生日/纪念日/约定时间），
    #   不是「句子里出现了时间词」。
    #
    #   验证：「你生日是几号」「下个月几号搬」仍然命中，
    #        「你什么时候醒的」不再命中。
    r"几号|几月|哪天",
]

