# ═══════════════════════════════════════════════════════════════
# 2026-11-12：新增两类，用于「入库打标签」。
#
# 为什么单独加，而不是继续塞进 event：
#   · test  —— 测试句/占位符进了长期库，会永远当答案被召回
#   · meta  —— 讨论「系统出了什么问题」的流水，不是关于他的事实
#   两者都不是「事件」，判成 event 会让它们和真实经历混在一起。
#
# 为什么位置必须在 has_quote 之前：
#   现在只要内容含「他说/我回」就立刻判 event 0.65，走不到后面。
#   而这两类的典型样本恰好都带「他说…我回…」结构。
# ═══════════════════════════════════════════════════════════════

# 测试类：只认「明确就是测试」的形态，不做内容推测。
#   为什么这么严：实测把「测试」当关键词会命中 71 条，其中 70 条是真实对话
#   （主题被标成「临时:xxx」而已）。误判测试类 = 真实记忆被永久排除召回。
TEST_CONTENT_PATTERNS = [
    r"^\s*测试\s*[:：]",            # 「测试：远程主机已经装好…」
    r"^\s*测试\s+add\b",            # 「测试 add 会不会触发巩固」
    r"^\s*\[\s*测试\s*\]",
    r"审计隔离",                     # 隔离测试专用标记
    r"^\s*临时\s*[:：]\s*第\s*0\s*条",
    r"这是测试数据|测试用数据|请忽略这条",
]

# 元讨论：讨论「系统本身」的记录。
#
# 为什么用「三组共现」而不是单词：
#   实测单词表（含「记忆」「召回」）命中 30 条，其中混着
#   「记忆库搬到 D 盘」（真实事件）、「女仆最简」（画图模板）。
#   要求同时出现不同组别的词，才能把「讨论系统问题」和「记录系统的决定」分开。
META_GROUP_A = [r"召回", r"检索", r"向量库", r"embedding", r"语义召回", r"长期库检索"]
META_GROUP_B = [r"排到", r"排名", r"第[\s\d]+名", r"第[\s\d]+条", r"排不进", r"匹配上", r"失准", r"误判",
                # 2026-11-13 补：实测「排在首位的是一条技术讨论记录 /
                #   评分较高也可能答非所问」被判成事件 ——
                #   它讨论的就是召回质量，只是说法是「召回到第一条」「第一名」，
                #   而上面几条要的是「排到第N名」。同一件事的不同说法。
                r"召回到", r"第[一二三四五六七八九十]名", r"第一名", r"分数高不等于",
                r"三成是错", r"答案对"]
META_GROUP_C = [r"长期库", r"短期层", r"记忆库", r"window", r"池子", r"情景档", r"巩固", r"阈值", r"decay", r"pending",
                # 2026-11-13 补：讨论召回质量的记录常用「技术流水/答案/分数」这类词，
                #   而没有「长期库」这种库结构词。实测：
                #   「排在首位的是一条技术讨论记录 / 高分也可能偏题」
                r"技术流水", r"答案对不对", r"答案对", r"分数", r"召回质量", r"没答案的问题",
                # 2026-11-13 补：实测「语义召回失效：目标记录未进入前十」
                # 只有 A+B 没有 C，被判成事实而不是元讨论。
                # 这几条是「讨论检索效果」时几乎必说的词——名次、条目位置、失败。
                r"第\s*\d+\s*名", r"\d+\s*/\s*\d+", r"名里", r"排不进", r"失效", r"没修", r"没做",
                # ★ 2026-11-13 再补：**单个功能的故障**也是元讨论，但上面这些库结构词
                #   一个都不含。实测漏掉 3 条（改前判成闲聊，会正常参与召回）：
                #     「定时器的 bug 还没修好，设定时长后仍显示默认值」
                #     「天气接口请求失败是因为缺少认证头」
                #     「日志写入需要原子替换，否则进程退出时可能留下空文件」
                #   这三条留在闲聊里，问「睡眠设置怎么弄」时会被当答案召回 ——
                #   正是最早那个「讨论 bug 的流水抢到第一名」问题的翻版。
                #   实测：这条规则只多抓 3 条，3 条全对，零误伤。
                r"(?:潜水|睡眠|记忆|召回|检索|桥接|接口|插件|工具|脚本|阈值|参数|配置|模型|音色|端口|部署)"
                r"[^。；]{0,14}(?:bug|报错|没修|失效|调不通|没落上|不生效|没反应|跑不通|崩)"]
# 功能出故障 = 元讨论（单独一条通道，不要求共现）
META_FEATURE_BUG = [
    r"(?:潜水|睡眠|记忆|召回|检索|桥接|接口|插件|工具|脚本|阈值|参数|配置|模型|音色|端口|部署)"
    r"[^。；]{0,14}(?:bug|报错|没修|调不通|没落上|不生效|没反应|跑不通|崩了)",
]

# 决策句式：说明这是「定下来的做法」，不是「出了什么问题」
META_DECISION = [
    r"(?:约定|决定|规则是|以后都|一律)[^。；]{0,14}(?:要|用|进|走|做|加|改)",
    r"(?:以后|下次)[^。；]{0,10}(?:都|一律)",
]


def _is_test_content(c: str, src: str) -> bool:
    for pat in TEST_CONTENT_PATTERNS:
        if re.search(pat, c):
            return True
    # source 侧只认明确的测试来源标记，不能宽泛匹配「测试」二字
    if re.search(r"(?:^|[_\-])test(?:[_\-]|$)|audit_isolation", src):
        return True
    return False


def _is_meta_record(c: str) -> bool:
    """讨论「系统出了什么问题」→ True。

    ⚠️ 不能叫 `_is_meta_discussion`：本文件第 919 行已有同名函数
    （用于印象层的技术词密度判定），后定义会覆盖前者 —— 实测踩过。

    必须三组里至少两组共现，且不是决策句式。
    单组命中不判 —— 实测会误伤真实事件（「记忆库搬到 D 盘」）。
    """
    # ★ 2026-11-13：**功能出故障**单独一条通道，不要求三组共现。
    #
    #   为什么单独判：这类记录只含一个功能词 + 一个故障词，
    #   命中不了 A 组（检索词）也命中不了 B 组（排名词），
    #   按「至少两组」永远漏掉。但它讨论的就是系统本身。
    #
    #   实测只多抓 3 条，3 条全对，零误伤：
    #     「定时器的 bug 还没修好，设定时长后仍显示默认值」
    #     「天气接口请求失败是因为缺少认证头」
    #     「日志写入需要原子替换，否则进程退出时可能留下空文件」
    if re.search(r"[「“][^」”]{2,40}[」”].{0,25}(?:排到\s*\d|排第\s*\d|召回.{0,8}(?:失败|0\s*条)|Top\s*\d)", c, re.I):
        return True
    if any(re.search(p, c) for p in META_FEATURE_BUG):
        # 决策句式仍然放行（「约定：接口以后都用这个」）
        for pat in META_DECISION:
            if re.search(pat, c):
                return False
        return True

    hits = 0
    for group in (META_GROUP_A, META_GROUP_B, META_GROUP_C):
        if any(re.search(p, c) for p in group):
            hits += 1
    # 2026-11-12：必须命中 C 组（库结构词）。
    #   为什么：实测「检查间隔二十分钟，命中率过半」这类相处约定
    #   命中 A+B 后被误判成元讨论 —— 「命中」既是检索术语也是概率术语。
    #   真正讨论系统的记录几乎一定会提到库/表/字段，所以 C 组做硬性前提。
    if not any(re.search(p, c) for p in META_GROUP_C):
        return False
    if hits < 2:
        return False
    # 决策句式：这是在记录「定下来的做法」，应当保留
    for pat in META_DECISION:
        if re.search(pat, c):
            return False
    return True


def classify_importance(content: str, source: str = "") -> tuple:
    """按内容形态判定 (分类, 重要度)。不依赖 tags。

    2026-11-04 v3 修：source 也要参与 ——
      · manual_remember / 她自己记 = 他亲口让记的，起步就高
      · bridge_auto = 桥接自动记的流水，正常按内容判
    """
    c = (content or "").strip()
    if not c:
        return "empty", 0.30

    # 来源优先：他亲口让记的，至少给到 fact 档
    src = (source or "").lower()
    if "manual_remember" in src or "她自己记" in src:
        # 即使内容是寒暄，他让记的也值得重视（但不至于 0.92）
        return "manual", 0.85

    # 2026-11-06：承诺/约定 优先级最高（比 fact 还高），命中直接 L3，不跟短期衰减走
    # 2026-11-07 修：只看「承诺动词」，时间词（明天/以后）不再单独构成承诺 ——
    #   否则「明天还要早起，好烦」这种抱怨会被当成承诺永久记住。
    #
    # 2026-11-10 加排除：「约定/约好」的名词用法（「这个约定」「按约定」）
    #   不该算承诺。拆成「先匹配 + 再排除」两步，比写一条巨型正则更可验证。
    _commit_hit = None
    for pat in COMMITMENT_PATTERNS:
        if re.search(pat, c):
            _commit_hit = pat
            break
    if _commit_hit:
        _excluded = any(re.search(e, c) for e in COMMITMENT_EXCLUDE)
        if not _excluded:
            return "commitment", 0.92
        # 被排除的，继续往下走正常分类（多半落 event/speech）

    # ★ 2026-11-10 新增：重大医疗/生命事件 → event，但 fact 级分量（0.92）。
    #
    #   为什么放在承诺之后、日期/事实之前：
    #     如果一句里既有承诺又有「手术」（"我答应陪他去做手术"），
    #     承诺的意图更强，先返回 commitment 是对的。
    #     但在 date/fact 之前：医疗事件比一个日期数字更重要，
    #     不该因为句子里恰好有「3点」就被判成 date。
    #
    #   为什么类别用 event 不用 fact：
    #     「他家人住院了」是一件事，不是恒久事实。
    #     旧代码靠 `住.{1,8}` 把它捎带成 fact —— 类别是错的，只是分量对。
    #     现在类别和分量都对了。
    for pat in CRITICAL_EVENT_PATTERNS:
        if re.search(pat, c):
            return "event", 0.92

    # 只有时间词、没有承诺动作 → 不算承诺。
    # 但如果同时带「对话引号/事件描述」，说明是具体约好的事，按 event 记；
    # 否则继续往下走正常分类。
    _has_time_hint = any(re.search(p, c) for p in TIME_HINT_PATTERNS)

    # ★ 2026-11-11 修（重大）：对话流水判断提前到 date/fact **之前**。
    #
    #   为什么：原来 has_quote 的判断在 date/fact 之后，于是「他说…我回…」
    #   的对话流水里只要出现「12:44」「必须写」「不许跑」这类词，就被
    #   date/fact 提前截胡判成 0.92，根本走不到 event 兜底。
    #
    #   实测（pending 17 条全中招）：
    #     「他说：清单共有 25 条：已核对 13…」→ 命中「1：」→ 判 date
    #     「他说：只写方案不许跑」                  → 命中「不许跑」→ 判 fact
    #     「他说：必须写文档」                      → 命中「必须写」→ 判 fact
    #   这 17 条全是「用户指挥我修系统」的元对话，被误判成承诺/日期/事实，
    #   明天巩固会当 L3 打进长期库。
    #
    #   修法：has_quote 为真（对话流水）→ 直接 event 0.65，
    #         **不再**往下走 date/fact 的关键词命中。
    #   为什么安全：
    #     · 真承诺（「我答应你明天三点叫你」）已经在上面 COMMITMENT 段拦截
    #     · 医疗事件（「他家人住院了」）已经在上面 CRITICAL_EVENT 段拦截
    #     · 所以走到 has_quote 这里的，都是没有承诺/医疗的普通对话流水
    #     · 这些流水里出现的日期/规则词，是「对话内容」，不是「要记住的事实」
    #
    #   验证（17 条 pending 真实内容）：
    #     原版判 fact/date：17 条
    #     修复版判 fact/date：0 条（全部正确落回 event）
    has_third = bool(re.search(r"[他爸]", c))
    # ★ 2026-11-11 修：has_quote 不再认「「」」这个中文引号。
    #
    #   原来：("我回" in c) or ("他说" in c) or ("「" in c)
    #   问题：「「」」在人设/偏好文本里到处是——「被叫「胖」我会炸毛」
    #        「「大肥鱼」这个外号是他叫的」→ 被判成对话流水 → event 0.65
    #        于是后面的 persona 判据（在 not has_quote 分支里）永远走不到。
    #
    #   实测：6 条人设内容里 1 条因此没被识别。
    #
    #   修法：只有明确的对话标记才算对话流水：
    #     · 「他说」/「我回」= 桥接拼接的对话格式（这是最可靠的信号）
    #     · 「他说：」后面跟冒号 = 更明确的引用
    #   中文引号「」单独出现不算。
    has_quote = ("我回" in c) or ("他说" in c) or ("他说：" in c)
    # 「和朋友一起/弄通/折腾」这类是共同经历，不是工具知识
    is_event_desc = bool(re.search(r"一起|弄通|折腾|第一次|那天", c))

    # 2026-11-12：测试 / 元讨论**不在这里返回**，见文件末尾的
    #   classify_for_gate()。原因：本函数的第二个返回值会被
    #   infer_importance 直接拿去当重要度，而 infer_importance 被
    #   MemoryItem.__init__、decay_logic（4 处）、memory_health 共用。
    #   在这里塞 test(0.20)/meta(0.45) 会把这些真实记忆的重要度拉低，
    #   导致它们加速衰减 —— 改分类不该顺带改生命周期。

    # 事件优先：有对话引号（"他说/我回/「"）就是对话记录，直接判 event
    #   （不再要求长度 —— 短对话「他说：好晚了；我回：快睡」也是共同经历）
    if has_quote:
        return "event", 0.65

    # 只有「非对话」的内容（人设卡、工具说明、规则文本）才走 date/fact。
    #   这些没有「他说…我回…」结构，是系统自己/朋友让记的稳定信息。
    for pat in DATE_PATTERNS:
        if re.search(pat, c):
            return "date", 0.92

    for pat in FACT_PATTERNS:
        if re.search(pat, c):
            return "fact", 0.92

    if is_event_desc and has_third:
        return "event", 0.65
    # 2026-11-07：只有时间词、没有承诺动作，但提到「他/爸」→ 是约定/安排，按事件记
    #   （「明天十点去找他」这种属于事件，不是承诺，也不该被当噪音丢掉）
    if _has_time_hint and has_third:
        return "event", 0.65

    # 2026-11-11 二修：LESSON/LIMIT 只在「不是对话记录」时生效。
    #   has_quote 为真说明这是「他说…我回…」的流水，里面出现「不行/不能」
    #   是对话内容，不是她总结的教训 —— 不能因此判高。
    if not has_quote:
        for pat in LESSON_PATTERNS:
            if re.search(pat, c):
                return "lesson", 0.85
        for pat in LIMIT_PATTERNS:
            if re.search(pat, c):
                return "limit", 0.70
        # ★ 2026-11-11 新增：人设/偏好 → persona 0.85
        #
        #   为什么放在 lesson/limit 之后、tool/speech 之前：
        #     · lesson/limit 更具体（踩过的坑、能力边界），优先匹配
        #     · 但必须排在 speech 之前！否则「我平时喜欢简洁直接的风格」
        #       因为以「我」开头被判成 speech 0.22（几乎必忘）
        #     · 也排在 tool 之前：「这份笔记分为两部分…模型是示例模型」
        #       含工具词会被判 tool 0.60，但它是身份档案，该是 0.85
        #
        #   只在 not has_quote 时生效：带「他说…我回…」的是对话流水，
        #   里面出现「我最喜欢」是在跟用户说话，不是档案。
        for pat in PERSONA_PATTERNS:
            if re.search(pat, c):
                return "persona", 0.85

    # 工具知识优先于 speech 判断（「我怎么说话：Breeze」是工具，不是寒暄）
    if any(t in c for t in TOOL_KEYWORDS):
        return "tool", 0.60

    # speech：她的原话短句（不含工具、不含事件）
    if c.startswith(HER_SPEECH_START) and not has_third and len(c) <= 35:
        return "speech", 0.22
    if c.startswith(HER_SPEECH_START) and len(c) <= 20:
        return "speech", 0.22

    if has_third and len(c) > 60:
        return "event", 0.65
    if has_third:
        return "about_him", 0.55
    return "misc", 0.35


def infer_importance(content: str, source: str = "") -> float:
    return classify_importance(content, source)[1]


# ═══════════════════════════════════════════════════════════════════
# 入库门控分类（2026-11-12 新增）
#
# 为什么单独一个函数，而不是改 classify_importance：
#   classify_importance 的第二个返回值被 infer_importance 取走当重要度，
#   而 infer_importance 被 MemoryItem.__init__、decay_logic（4 处）、
#   memory_health 共用。在那里塞 test(0.20)/meta(0.45) 会让真实记忆
#   的重要度被拉低、加速衰减 —— 分类不该顺带改生命周期。
#
# 这个函数只服务于两件事：
#   ① 入库时打召回标签
#   ② 召回时决定要不要把这条放进答案池
# 它**不参与**重要性判定、不参与衰减。
# ═══════════════════════════════════════════════════════════════════

RECALL_YES = "yes"          # 正常记忆，参与召回
RECALL_META_ONLY = "meta_only"   # 元讨论，只在元问题下召回
RECALL_NO = "no"            # 测试/空壳，永不召回

# ═══════════════════════════════════════════════════════════════════
# 内容分类（kind）—— 2026-11-13 新增，**独立于 category**
#
# 为什么不放进 category：
#   category 这个字段现在被三样东西共用，已满：
#     ② "stable_profile"  稳定档案，渲染时加「一直：」前缀
#     ③ event/fact/...    老分类器的内容类别
#   结果是私密对话被当成普通记忆召回。这是隐私边界，不能碰。
#
# 所以新开 kind 字段，只回答「这条是什么」。
# ═══════════════════════════════════════════════════════════════════

KIND_FACT = "事实"
KIND_COMMIT = "约定"
KIND_EVENT = "事件"
KIND_EMOTION = "情感"
KIND_CHAT = "闲聊"
KIND_META = "元讨论"
KIND_TEST = "测试"
KINDS = (KIND_FACT, KIND_COMMIT, KIND_EVENT, KIND_EMOTION,
         KIND_CHAT, KIND_META, KIND_TEST)

# 老分类器类别 → kind
_OLD_TO_KIND = {
    "commitment": KIND_COMMIT,
    "date": KIND_FACT,
    "fact": KIND_FACT,
    "about_him": KIND_FACT,
    "manual": KIND_FACT,
    "persona": KIND_FACT,
    "tool": KIND_FACT,
    "lesson": KIND_FACT,
    "limit": KIND_FACT,
    "event": KIND_EVENT,
    "notes": KIND_EVENT,
    "speech": KIND_CHAT,
    "misc": KIND_CHAT,
    "empty": KIND_CHAT,
}

# 情感判据：只认明确的感受词。
#
#   ⚠️ 2026-11-13 实测踩过：第一版拿 emotion_intensity >= 0.6 当判据，
#      结果 122 条被判成情感，绝大多数是工具说明 ——
#        「我怎么说话：TTS 语音合成…」「看屏幕用 screen_capture…」
#      它们的 emotion_intensity 被填了 0.6~0.9，但内容里一个情绪词都没有。
#      这个字段本身不可信，不能当情感判据。
_KIND_EMOTION_WORDS = re.compile(
    r"怕|担心|害怕|难受|委屈|想你|爱你|喜欢你|舍不得|难过|哭|"
    r"开心|高兴|心疼|孤单|不安|慌|在意|生气|吃醋|"
    r"忍不住|离不开|陪着我|别走|不理我"
)
# 约定声明式开头：「约定：明天七点叫你起床」「说好：以后都这样」
#
#   ⚠️ 2026-11-13 实测：COMMITMENT_PATTERNS 里那几条是**动作式**的
#   （「我答应你…」「我们说好要…」），而「约定：XXX」是**名词式标题**，
#   一条都对不上，结果被判成 misc(闲聊)。
#   这类在真实库里是「他明确交代、要长期遵守」的事，必须判约定。
_KIND_COMMIT_HEAD = re.compile(
    r"^\s*(?:约定|说好|定好|讲好|商量好|规则|规矩)\s*[:：]"
)
_KIND_CHITCHAT_ONLY = re.compile(
    r"^(?:嗯+|哦+|啊+|哈+|好+|行+|对+|是+|收到|在|晚安|早安|知道了|好的|可以|没事)"
    r"[呀啊哦呢吧了嘛~～。！?]*$"
)
# 功能描述句不算情感（「我用 X」「靠 Y」「默认 Z」或含工具词）
_KIND_FUNC_HINT = re.compile(
    r"(?:^|[，。；])\s*(?:我)?(?:用|靠|默认|可以|能|调用|打开)"
    r"|截图|接口|命令|参数|配置|脚本|工具|模型|音色|变调|端口"
)


def _looks_like_emotion(content: str) -> bool:
    """真实情绪表达 → True。纯寒暄、功能描述一律 False。永不抛。"""
    c = str(content or "").strip()
    if not c:
        return False
    if _KIND_CHITCHAT_ONLY.match(c):
        return False
    if _KIND_FUNC_HINT.search(c):
        return False
    # 「不怕 / 不担心 / 没什么好怕」是**否定**，不是情绪本身。
    #   实测「记忆库迁移结束，接下来验证备份」被判成情感 ——
    #   命中的是「怕」字，但语义是「不用怕」。
    if re.search(r"(?:不|没|别|不用|不必)(?:用)?(?:怕|担心|害怕|难受|慌)", c):
        # 但仍保留真正表达情绪的否定式，如「我忍不住不想你」
        if not re.search(r"忍不住|离不开|舍不得", c):
            return False
    return bool(_KIND_EMOTION_WORDS.search(c))


def classify_kind(content: str, source: str = "", mem=None) -> str:
    """这条记忆「是什么」。返回 KINDS 之一。永不抛。

    优先级：
      测试 > 元讨论 > 情感 > (情景档按主题) > 老分类器映射

    mem 可选：传进来时能拿到 mem_type / scene，用于情景档按主题判。
    """
    c = str(content or "")
    src = str(source or "").lower()

    if _is_test_content(c, src):
        return KIND_TEST
    if _is_meta_record(c):
        return KIND_META

    # 情景档：正文是拼接出来的（「11-07 18:31，睡（2 轮）。…」），
    #   分类器没有足够信息 —— 实测带时间前缀全判 date、去前缀全判 misc。
    #   所以用 episode.py 已经算好的 theme 判，那是更可靠的信号。
    if mem is not None and str(getattr(mem, "mem_type", "") or "") == "episode":
        if _looks_like_emotion(c):
            return KIND_EMOTION
        scene = getattr(mem, "scene", None) or {}
        theme = str((scene or {}).get("theme") or "") if isinstance(scene, dict) else ""
        kind = str((scene or {}).get("theme_kind") or "") if isinstance(scene, dict) else ""
        if theme in ("闲聊", "") or theme.startswith("临时:") or kind == "fallback":
            return KIND_CHAT
        return KIND_EVENT

    if _looks_like_emotion(c):
        return KIND_EMOTION

    # 约定声明式开头（「约定：明天七点叫你」）—— 老分类器认不出来，这里补
    if _KIND_COMMIT_HEAD.match(c):
        return KIND_COMMIT

    try:
        old, _ = classify_importance(c, src)
    except Exception:
        old = "misc"
    return _OLD_TO_KIND.get(old, KIND_CHAT)


def classify_for_gate(content: str, source: str = "") -> dict:
    """给一条记忆打「召回门控」标签。永不抛。

    返回：
        {
          "category": "test"|"meta"|<classify_importance 的原类别>,
          "importance": float,
          "recallable": "yes"|"meta_only"|"no",
          "tagged_by": "rule",
        }

    ⚠️ importance 一律沿用 classify_importance 的值，
       不因类别而调低 —— 见上方说明。
    """
    c = str(content or "").strip()
    src = str(source or "").lower()
    try:
        base_cat, imp = classify_importance(c, src)
    except Exception:
        base_cat, imp = "misc", 0.35

    if _is_test_content(c, src):
        return {"category": "test", "importance": imp,
                "recallable": RECALL_NO, "tagged_by": "rule"}
    if _is_meta_record(c):
        return {"category": "meta", "importance": imp,
                "recallable": RECALL_META_ONLY, "tagged_by": "rule"}
    return {"category": base_cat, "importance": imp,
            "recallable": RECALL_YES, "tagged_by": "rule"}


def is_recallable(content: str, source: str = "", query_is_meta: bool = False) -> bool:
    """这条记忆该不该进入答案池。永不抛。

    meta_only 只在 query 被判定为元问题时才放行；
    query 分类器上线前，调用方应传 query_is_meta=False（即 meta 一律不召回）。
    """
    info = classify_for_gate(content, source)
    r = info["recallable"]
    if r == RECALL_NO:
        return False
    if r == RECALL_META_ONLY:
        return bool(query_is_meta)
    return True


# ===== 2026-11-08 信任度 credibility（T06）=====
#
# 问题：strength 一个字段干两件事 ——
#   ① 多容易被想起来（会衰减）
#   ② 是不是真的（不该随时间变假）
# 后果：「他生日 2 月 13 日」三个月没提 → strength 掉到 25 → 被当成「快忘了」，
#   可它从来没有变假。
#
# 所以拆开：
#   strength     唤起权重，会衰减（decay_logic.calculate_current_strength 只碰它）
#   credibility  可信度 0~1，不随时间衰减，只在「被明确推翻」时才改
#
# 取值（《主系统设计》27.2）：
#   1.0  明确事实（他亲口说的/确认过的）—— 默认
#   0.85 比较确定（被多次提起、前后一致）—— 暂无自动写入者
#   0.6  不太确定（推测、模糊）
#   0.4  听别人说的
#   0.2  已被推翻（冲突检测判定）—— 暂无自动写入者
UNCERTAIN_PATTERNS = [
    (r'好像|似乎|大概|可能|也许|不确定', 0.6),
    (r'听说|别人说|他说别人|据说', 0.4),
]

CREDIBILITY_DEFAULT = 1.0


def infer_credibility(source: str, content: str) -> float:
    """按内容推断初始可信度，默认 1.0（不衰减，见 decay_logic 的说明）。

    为什么默认 1.0：库里绝大多数是「他说了 X」这种明确发生过的对话，
    默认给低分会让整个库都变成「不可信」，等于没做。

    命中多条时取**最低**的（最保守）：
      「听说他好像要买房」同时命中 0.4 和 0.6 → 取 0.4。
      可信度是「能不能拿它当事实用」，宁可低估不可高估。

    source 暂时不参与判断 —— 这一版只看措辞。
    留给将来的规则（如 learned/资讯日报 降权、被提及 3 次以上升到 0.85）。
    """
    c = str(content or "")
    best = CREDIBILITY_DEFAULT
    for pat, val in UNCERTAIN_PATTERNS:
        if re.search(pat, c):
            if val < best:
                best = val
    return float(best)



# ═══════════════════════════════════════════════════════════════════
# 情绪推断（2026-11-10 第一步）
# ═══════════════════════════════════════════════════════════════════
#
# 问题：emotion_intensity 一直是 0.0。
#
#   实测生产库 372 条：
#     emotion_valence:  neutral×369  positive×3
#     emotion_intensity >= 40:  只有 12 条（3%）
#     emotion_intensity >= 60:  0 条
#
#   而 decay_logic.emotion_decay_factor 早就写好了：
#     >= 60 → 衰减 ×0.4（慢 2.5 倍）
#     >= 40 → 衰减 ×0.7
#
#   **配置在，但从没被触发过** —— 因为没有写入者。
#
# 为什么这是「不像人」的核心原因：
#
#   人的记忆强度不只取决于「内容多重要」（那是 importance），
#   还取决于「当时多强烈」。一次吓一跳的事，比十次平淡的日常记得久。
#
#   现在系统只有 importance 一条轴：
#     「他家人住院了」和「他今天吃了面」都判 event，都是 0.65，地板都是 39。
#   这两件事对人的意义完全不同，但系统完全分不出来。
#
# 设计原则：
#   ① 只在**明确命中**时给分，命中不到就是 0.0（保持默认行为不变）
#   ② 取**最高**的那一档（与其他 fallback 的「取最低」相反）——
#      情绪是「有一处强烈就够了」，不像可信度要保守
#   ③ 不改 valence 的语义：只给 positive/negative，neutral 表示"没情绪"
#
# 放在这里而不是 decay_logic：它是数据初始化的一部分，
# 跟 infer_credibility / infer_importance 是同一类东西。

# (正则, valence, intensity)
# 强度档位设计（对应 config.EMOTION_DECAY_PROTECT 的两个阈值）：
#   85~95  创伤/重大事件  → 触发 >=60 档（慢 2.5 倍）
#   60~80  强烈情绪       → 触发 >=60 档
#   40~59  中等情绪       → 触发 >=40 档（慢 1.4 倍）
#
# ★★★ 2026-11-10 实测修正（第一版误判严重）★★★
#
#   第一版上线后拿生产库 372 条实测，命中 9 条（2.4%），但**几乎全是误判**：
#
#     误判 1：「他怕我不回消息是"不在了"」       命中"不在了" → 判 95
#             这是**比喻/引用**，不是死亡事件
#     误判 2：「今天把短视频那套新插件跑通了…」     命中"不在了" → 判 95
#             这跟死亡毫无关系（是"不在这个列表里"）
#     误判 3：「他说：你吃快点…连呼吸都顾不上」   命中"撑不住" → 判 85
#     误判 4：「又说：侧躺这个姿势最省劲…」       命中"撑不住" → 判 85
#             同上
#     误判 5：「腻在一起的时候…」                 命中"撑不住" → 判 90
#             同上
#
#   根因有三个，必须同时修：
#
#     ① **短语太泛**。"不在了""撑不住""受不了"在日常语境里大量出现，
#        不能当死亡/崩溃的信号。要么删掉，要么加限定词。
#     ② **没排除引号内容**。系统里记忆内容常是「他说：X；我回：Y」，
#        引号里是角色扮演/转述，不该按字面判情绪。
#     ③ **没有否定/假设语境**。"怕我不回消息是'不在了'" 是**担心**，
#        不是**发生**。
#
#   修法：
#     · 强信号词加限定：死亡类必须同时出现"去世|走了|葬礼|讣"等明确词
#       "不在了"单独出现不算
#     · "撑不住"限定为身体/精神语境（"撑不住了""快撑不住"），
#       排除"把…撑住"
#     · 新增 `_strip_quoted()`：判断前先剥掉引号内内容？
#       ❌ 不行 —— "他说：我好害怕" 引号里才是真情绪
#       ✅ 正确做法：只对**高误判风险**的词做上下文检查
#
EMOTION_PATTERNS = [
    # ── 创伤 / 重大医疗：必须明确，不能靠"不在了"这种泛词 ──
    (r'住院|手术|急诊|抢救|ICU|重症|化疗|确诊|病危|住院了', 'negative', 90),
    # ★ 2026-11-10 独立审查指出：`走了` 在中文里默认就是「离开/先走」，
    #   把它当死亡信号会误伤大量日常对话（"他说我先走了" "东西都带走了"）。
    #   真正表达死亡的说法是「不在了 / 过世 / 走了以后」这类**带上下文**的。
    #   所以从 95 档删掉 `走了`，只保留语义无歧义的。
    #
    # ★ 二次修正（同一审查）：`不在了` 也必须删。
    #   实测：「他怕我不回消息是"不在了"」是个**比喻**，被判 95。
    #   它跟「走了」一样，单独出现时无法区分"离世"和"不在某个列表/状态里"。
    #   真正可靠的死亡信号是「去世/过世/离世/逝世」这类**只用于死亡**的词。
    (r'去世|过世|离世|逝世|离开我们|葬礼|追悼|讣告', 'negative', 95),
    (r'车祸|摔伤|受伤|流血|骨折|缝针', 'negative', 85),
    (r'辞职|失业|被裁|破产|欠债', 'negative', 80),

    # ── 强烈负面：限定为心理语境，排除动作描写 ──
    (r'崩溃|绝望|想死|活不下去|活着没意思', 'negative', 85),
    (r'吵架|吵起来|发火|凶我|骂我|摔门|冷战', 'negative', 75),
    (r'委屈|难过|伤心|心疼|心酸', 'negative', 70),
    (r'哭了|哭着|掉眼泪|红着眼|哽咽|抽泣|哭了很久', 'negative', 75),
    (r'害怕|好怕|吓死|恐惧|发抖', 'negative', 65),
    # ★ "撑不住"必须跟情绪词一起出现，否则是动作描写
    (r'(撑不住|受不了).{0,6}(哭|难过|委屈|崩溃|眼泪)', 'negative', 80),
    (r'焦虑|烦躁|睡不着|失眠|压力大', 'negative', 55),

    # ── 强烈正面 ──
    # ★ 修正：原来 `惊喜` 单独出现就给 75，实测误判——
    #   「他说：等会给我惊喜；我回：别开玩笑了」是玩笑，不是"重大喜事"。
    #   现在要求"惊喜"跟情绪反应词一起出现才算。
    (r'求婚|结婚|领证|在一起了', 'positive', 90),
    (r'(惊喜|感动).{0,8}(哭|开心|感动|流泪|不行了)|太开心|特别开心|开心死|好开心', 'positive', 75),
    # 想念的对象是某个具体的人。刻意不用「我想他」——
    #   "我想他明天会回来" 是「认为」，不是想念。
    (r'想(你|他|她)了|好想(你|他|她)', 'positive', 65),
    # ★ 修正：`生日` 命中率极高（生日字段、生日约定、生日祝福），
    #   而且是"事实"不是"情绪事件"。降到 40，不建印象层。
    #   真正该保护的是「生日那天发生了什么」，那由 event + 内容判断。
    (r'生日|纪念日|周年', 'positive', 40),
    (r'(考上|升职|加薪)(了|成功)', 'positive', 65),
    (r'谢谢|感谢|辛苦了|有你真好', 'positive', 40),

    # ── 中等强度 ──
    (r'生病|发烧|感冒|不舒服|头疼|胃疼', 'negative', 50),
    (r'加班|熬夜|累死|好累|疲惫', 'negative', 45),
    (r'担心|不放心|挂念|惦记', 'negative', 40),
]

# 需要排除的语境：命中这些词时，上面的强信号不算数
#
# ★ 2026-11-10 实测第二版修正（第一次修完仍有 6 条误判，逐个查了原文）：
#
#   误判 4：「…照他给的图走了一遍流程…」        命中"走了" → 判 95
#            原文是「走了一遍流程」，不是"人走了"
#   误判 5：「…崩溃留下的半份备份没人看得见…」  命中"崩溃" → 判 85
#            原文是**技术讨论**（程序崩溃），不是情绪崩溃
#   误判 6：「朋友半夜问我：是不是不想聊了」 命中"喜欢你" → 判 65
#            原文是**引用一个问题**，不是表达喜爱
#
#   根因：这些词在**技术讨论 / 描述性 / 引用**语境里大量出现。
#   修法：加两道守卫——
#     ① 技术词守卫：内容含大量技术词时，整体不判情绪（它是元讨论）
#     ② 明确的词组排除：`走了` 排除「走了一遍/走流程/走开」等
#
#   注意：不能用"剥掉引号内容"的办法 ——
#         「他说：我好害怕」里引号内才是真情绪，剥掉就漏了。
#         所以只能"整体语境判断 + 具体误判词排除"。

# ① 技术/元讨论语境：命中 >= 2 个就整体跳过情绪推断
_META_TECH_WORDS = (
    '备份', '回滚', '插件', '脚本', '接口', '参数', '函数', '模块', '阈值',
    '工具', '目录', '文件', '权限', '规则', '清单', '验证', '测试', '日志',
    'token', 'bug', 'JSON', 'API', 'embedding', '向量', '衰减', '召回',
    '记忆库', '候选池', '巩固', 'schema', 'config', 'commit', '部署',
)

# ② 具体误判词：这些组合出现时，对应的高分 pattern 不算
#    (要排除的正则, 会被它误伤的 pattern 关键词)
_FALSE_POSITIVE_GUARDS = (
    (r'走了一遍|走流程|走开|走出去|走完|走势|走神|走错', '走了'),
    (r'崩溃[^，。；]{0,6}(备份|数据|进程|程序|服务|后|留下)', '崩溃'),
    (r'(备份|数据|进程|程序|服务|工具)[^，。；]{0,6}崩溃', '崩溃'),
    # ★ 交接后新增：「崩溃日志/报告/堆栈」是技术词
    #   原 guard 只认 备份|数据|进程…，漏了「日志」
    (r'崩溃日志|崩溃报告|崩溃堆栈|崩溃[^，。；]{0,6}(日志|报错|堆栈)', '崩溃'),
    (r'(拍一拍|戳了戳|谢谢|感谢|辛苦了)', ('谢谢', '感谢', '辛苦了')),
    #   「否定式引述 + 情绪词」是一个高频误判结构，跟第一版误判
    #   （「他怕我不回消息是"不在了"」）同源。
    #
    #   实测那条技术记录里的「委屈」出现在：
    #       「他发了一堆说明，说那不是抱怨只是提醒」
    #   → 这是**引述别人的话**，不是自己有情绪。
    #
    #   这条 guard 看的是**语法局部性**（否定/转折结构），
    #   比「技术词密度」精确 —— 密度对长文本天然失效。
    #
    #   ⚠️ 但只覆盖「否定式引述」这一种结构，
    #      命中率大概从 20% 提到 30%，本质问题解决不了。
    #
    #   ★ 实现注意（我第一次写错了）：keyword 是**逐词元组**，不是
    #     `'a|b|c'` 字符串 —— `_is_false_positive` 用的是
    #     `keyword in hit_text`（子串匹配），拿整串比单个命中词永远不成立。
    (r'不是\S{1,4}是\S{1,4}|不是.{0,4}而是|说那(不是|不算)',
     ('委屈', '难过', '伤心', '心疼', '心酸', '崩溃')),
)


def _is_meta_discussion(content: str) -> bool:
    """是不是在讨论技术/系统本身，而不是在表达情绪。

    ★ 2026-11-10 独立审查抓出的严重缺陷（实测复现）：
      原实现是 `hits >= 2` 就整条归零。在一个「技术记录 + 生活对话」
      混在一起的库里（作者本人的库就是这样），这条判据极其脆：

        [ 90.0] 他住院了，我在病房陪床
        [ 90.0] 他住院了，我在病房陪床，顺手改了个脚本     ← 1 个词，活着
        [  0.0] 他住院我在陪床，顺手更新了日志和文件       ← 2 个词，归零

      同一件事，多写「日志」「文件」两个词就从 90 变 0。
      实测 6 条生活场景被清零：

        用户说他累死了，还要写脚本看日志
        朋友今天很累，加班到凌晨，日志文件都没看
        他住院了，我守着手机看部署日志
        他辞职了，那些规则清单我都留着
        他哭了，说工具目录全丢了

    ★ 修法：从「绝对个数」改成「技术词密度」。
      阈值取 0.12（每 100 字出现 12 个技术词才算技术文档）。
      依据实测：
        · 纯技术记录（插件/接口/参数/模块）：密度 0.3~0.8
        · 生活对话里顺带提一句：密度 0.02~0.08
        · 上面那 6 条被误杀的生活场景：密度 0.05~0.09

      同时保留一条硬规则：**只要命中了「强情绪信号」（95 档的
      去世/葬礼 等），就不做技术讨论判定** —— 因为「他去世了」后面
      跟一句技术词汇，仍然是「他去世了」。
    """
    c = str(content or "")
    if not c:
        return False

    # 硬规则：极强情绪信号优先，不许被技术词冲掉
    #
    # ⚠️ 2026-11-10 修正：`不在了` 曾经从后门回来过。
    #   第一版误判修正时，正是因为「他怕我不回消息是"不在了"」这个比喻，
    #   把它从死亡 pattern 里删掉了。结果修 _is_meta_discussion 时又塞进
    #   这个硬规则里 —— 它比之前更糟，因为这里是「直接 return False」，
    #   连 pattern 匹配都跳过了。
    #   实测回归：`他怕我不回消息是"不在了"…` → 又被判 95。
    #
    #   所以只保留语义无歧义的词。
    _STRONG_EMOTION = (
        r'去世|过世|离世|逝世|葬礼|追悼|讣告|'
        r'住院|手术|急诊|抢救|ICU|重症|化疗|病危'
    )
    if re.search(_STRONG_EMOTION, c):
        return False

    hits = sum(1 for w in _META_TECH_WORDS if w in c)
    if hits == 0:
        return False

    # ★ 2026-11-10 独立审查（问题 A）：密度阈值对长文本天然失效。
    #
    #   实测：一条 312 字的技术记录命中 3 个技术词（插件/文件/权限），
    #        密度 = 3/312 = 0.0096 → 要触发需要 38 个技术词。
    #        一条 500 字的技术记录需要 60 个。
    #   ⇒ 长文本永远逃逸，第一版误判 2 换了个路径回来。
    #
    #   修法：**「绝对个数 >= 5」或「密度 >= 0.12」二选一。**
    #
    #     为什么是 5：
    #       · 纯技术记录通常有 5+ 个技术词（插件/接口/参数/模块/目录…）
    #       · 生活对话里顺带提技术词，一般 1~3 个
    #       · 5 是这两类的分界（实测那 6 条被误杀的生活场景是 2~3 个）
    #
    #     ⚠️ 副作用：一条很长、但确实在讲生活和技术的混合内容，
    #        只要有 5 个技术词就会被判成元讨论。**这是有意的**——
    #        宁可漏判情绪，也不要把技术文档写进印象层。
    if hits >= 5:
        return True
    density = hits / max(len(c), 20)
    return density >= 0.12


def _is_false_positive(content: str, matched_text: str) -> bool:
    """命中的那段文本是否落入了已知误判语境。

    ★ 2026-11-10 独立审查把我前两版实现都打回来了，这是第三版。

      版本历史（每一版都是被实测推翻的）：

        v1  `keyword in matched_pattern` —— 拿**整条 pattern 字符串**比对
            实测：'奶奶去世了，他走了一遍流程办后事'
                  pattern='去世|走了|离开我们|葬礼|追悼|讣告'
                  「走了」在 pattern 里 → guard 命中 → 整条作废 → 判 0 分
                  ⇒ 「奶奶去世」被「顺便走了个流程」清零

        v2  按 `|` 盲拆 + 逐词 re.search
            实测：**直接崩溃**。因为 pattern 里有带分组的片段：
                  `(撑不住|受不了).{0,6}(哭|…)` 拆开后是 `(撑不住` 这种
                  未闭合括号 → re.error: missing ), unterminated subpattern
                  ⇒ 只要命中「好开心」就抛异常
                  ⇒ 而 from_dict 没有 try，**一条脏记忆会让整个库加载失败**

        v3（当前）**不拆 pattern**，直接用 `re.search().group(0)`
            —— 正则引擎已经帮我们算出「真正命中的那段文本」了，
               不需要自己解析 pattern 结构。

      ⚠️ 为什么必须用 group(0) 而不是拆字符串：
         正则表达式不是「用 | 分隔的词表」。带分组的、
         带量词的、带字符类的都不能按 `|` 拆。
         唯一的可靠来源是正则引擎自己的匹配结果。

    参数：
      content      原文
      matched_text 该 pattern 在 content 里**真正命中的文本**（m.group(0)）
    """
    c = str(content or "")
    hit_text = str(matched_text or "")
    if not hit_text:
        return False
    for guard_re, keyword in _FALSE_POSITIVE_GUARDS:
        # keyword 可以是单个字符串，也可以是元组（2026-11-10 新增）
        keywords = keyword if isinstance(keyword, (tuple, list, set)) else (keyword,)
        if not any(k and k in hit_text for k in keywords):
            continue
        try:
            if re.search(guard_re, c):
                return True
        except re.error:
            continue        # guard 正则本身有病 → 不排除
    return False

EMOTION_DEFAULT_INTENSITY = 0.0




# ═══════════════════════════════════════════════════════════════
# 修复层（2026-11-10 交接后新增，对应 KNOWN_ISSUES ① ②）
# ═══════════════════════════════════════════════════════════════

# ② 转折句：「不是因为难过，是因为高兴」「不是伤心是感动」「不是他难过，是我难过」
#    只取「是」后面那半句判情绪；「不是」之前的内容单独判（如「她哭着说」）。
_CONTRAST_RE = re.compile(
    r'不是(?:因为)?[^，。；,;]{1,6}[，,]?\s*(?:而)?是(?:因为)?([^。；;]{1,10})'
)

_CONTRAST_POSITIVE_RE = re.compile(r'高兴|感动')

# ① 「转述用户的习惯/偏好/要求」句式，不计作助手自身的情绪。
#    以子句为单位判断；强事件（>=80，如住院/去世）不受影响。
#    「要」后面接 哭/崩溃/疯/死 时不算要求句（「他难过得要哭」仍是情绪）。
_REPORTING_RE = re.compile(
    r'^(?:用户|他|她)[^，。；]{0,14}?(?:喜欢|经常|总是|习惯|爱听|'
    r'睡前|平时|每天|总爱|老是|动不动|'
    r'别(?!提|扭|人|的|处|说)|需要|要(?!哭|崩|疯|死))'
)
_CLAUSE_SPLIT = re.compile(r'[，。；！？!?\n]')
_REPORTING_MAX = 80   # 子句强度 >= 此值则不当作「记录」丢弃


def _infer_core(c: str) -> tuple:
    """原始规则循环（逐字保留原逻辑，仅抽成函数）。"""
    # ── 以下为旧实现，保留在 _infer_core 里 ──
    best_valence = "neutral"
    best_intensity = EMOTION_DEFAULT_INTENSITY
    for pat, valence, intensity in EMOTION_PATTERNS:
        if intensity <= best_intensity:
            continue
        # ★★★ 2026-11-10 独立审查抓出的 P0 崩溃（必须保留这个 try）★★★
        #
        #   这一行原来是裸的 `m = re.search(pat, c)`。
        #   而 EMOTION_PATTERNS 里有 3 条 pattern 带分组：
        #       80  (撑不住|受不了).{0,6}(哭|难过|委屈|崩溃|眼泪)
        #       75  (惊喜|感动).{0,8}(哭|开心|感动|流泪|不行了)|太开心|...
        #       65  (考上|升职|加薪)(了|成功)
        #
        #   它们本身是**合法**正则 —— 但我在 _matched_terms(v2) 里按 `|` 拆开
        #   再逐段 re.search，拆出的 `(撑不住` 是**未闭合括号** → re.error。
        #
        #   实测：
        #       infer_emotion('好开心啊今天')     → re.error
        #       infer_emotion('他说他撑不住了')   → re.error
        #
        #   而 MemoryItem.__init__ / from_dict 都会调它，加载路径是裸列表推导：
        #       [MemoryItem.from_dict(d) for d in data["memories"]]
        #   ⇒ **一条脏记忆会让整个长时库加载不出来**（不是跳过，是中断）。
        #
        #   这正好是本文件 _normalize_numeric_fields 的 docstring 警告过的：
        #     「不能因为一条脏行就让整个库加载失败 —— 那等于全库不可用」。
        #
        #   所以这里必须有 try：单条 pattern 有病，只跳过它，不连累整次推断。
        try:
            m = re.search(pat, c)
        except re.error:
            continue
        if not m:
            continue
        # 守卫 ②：命中但落入已知误判语境 → 跳过这条 pattern
        #   用 m.group(0)（真正命中的文本），不解析 pattern 结构
        try:
            if _is_false_positive(c, m.group(0)):
                continue
        except Exception:
            pass      # 守卫坏了就当作"不是误判"，宁可记录也不丢
        best_intensity = intensity
        best_valence = valence
    return best_valence, float(best_intensity)


def _infer_plain(c: str) -> tuple:
    """子句级「记录 vs 情绪」过滤 + 规则判定。"""
    kept = []
    for clause in _CLAUSE_SPLIT.split(c):
        cl = clause.strip()
        if not cl:
            continue
        if _REPORTING_RE.search(cl) and _infer_core(cl)[1] < _REPORTING_MAX:
            continue          # 关于用户的习惯/偏好/要求 → 不计助手的情绪
        # 「说 + 短句」是引述对方的话（<=12 字且不含括号）
        if (re.match(r"^(?:他|她)?说(?:：|:)?\s*", cl) and len(cl) <= 12
                and not re.search(r"[（(]", cl)):
            continue
        kept.append(cl)
    if not kept:
        return "neutral", EMOTION_DEFAULT_INTENSITY
    # 用逗号重新拼接，保证守卫②（整句语境）仍能工作
    return _infer_core("，".join(kept))


def infer_emotion(content: str, source: str = "") -> tuple:
    """按内容推断 (valence, intensity)。命中不到返回 ("neutral", 0.0)。

    为什么取最高档而不是最低档：
        可信度是「能不能当事实用」，宁可低估；
        情绪是「这件事对我有多重」，有一处强烈就该记下来。
        「他家人住院了，我吓死了」同时命中 90 和 65 → 取 90。

    为什么不影响默认行为：
        命不中任何模式时返回 0.0，跟现在的默认值完全一样。
        只有真的含情绪词的内容才会变。

    ★ 2026-11-10 两道误判守卫（实测逼出来的，见 _FALSE_POSITIVE_GUARDS 注释）：
        ① 技术/元讨论语境 → 整体跳过（0 分）
        ② 具体误判词组   → 单条 pattern 不计分

    source 暂不参与（跟 infer_credibility 一致，保持口径统一）。
    """
    c = str(content or "")
    if not c:
        return "neutral", EMOTION_DEFAULT_INTENSITY

    # 守卫 ①：技术讨论里出现的"崩溃/走了/受不了"不是在表达情绪
    try:
        if _is_meta_discussion(c):
            return "neutral", EMOTION_DEFAULT_INTENSITY
    except Exception:
        pass      # 守卫本身有 bug 时，不阻断推断
    # ── 修复 ②：转折句「不是X，是Y」→ 真意在 Y ──
    #   否定部分之外的证据（如「哭着」）另算，取强度更高者。
    m = _CONTRAST_RE.search(c)
    if m:
        head = c[:m.start()]
        tail = m.group(1)
        cand = [_infer_plain(tail), _infer_plain(head)]
        # 「高兴|感动」单独出现太泛（「很高兴认识你」），只在转折句后半句才认
        if _CONTRAST_POSITIVE_RE.search(tail):
            cand.append(("positive", 75.0))
        return max(cand, key=lambda r: r[1])

    # ── 主路径：_infer_plain（内含 _REPORTING_RE 记录过滤 + _infer_core 规则循环）──
    return _infer_plain(c)

def infer_emotion_intensity(content: str, source: str = "") -> float:
    """只要强度（跟 infer_importance 一样的薄封装）。"""
    return infer_emotion(content, source)[1]


# 2026-11-06 话题关键词抽取：给「场景化」和「语义联想」用。

# 2026-11-06 话题关键词抽取：给「场景化」和「语义联想」用。
# 从内容里抽出话题词，召回时 query 撞上这些词也算命中（不只看向量）。
TOPIC_HINTS = [
    "火锅", "电影", "游戏", "唱歌", "画图", "短视频", "猫", "狗", "宠物",
    "奶茶", "火锅店", "旅游", "演唱会", "音乐", "书", "动漫", "番剧",
    "考试", "上课", "加班", "熬夜", "生病", "吃药", "医院",
    "生日", "纪念日", "朋友", "同学", "家人",
]


def extract_topics(content: str) -> List[str]:
    """从内容里抽话题词（简单关键词匹配，不调模型）。"""
    c = str(content or "")
    found = []
    for t in TOPIC_HINTS:
        if t in c:
            found.append(t)
    return found


class MemoryItem:
    """统一记忆条目数据结构"""

    def __init__(
        self,
        content: str,
        mem_type: str = "working",          # sensory / working / long_term
        tags: Optional[List[str]] = None,
        emotion_valence: str = "neutral",   # positive / neutral / negative
        # ★ 2026-11-10（第一步 · jolly-cedar）：默认值改成 None（原 0.0）。
        #   None = 没传 → 按内容推断；0.0 = 显式声明"无情绪" → 保留。
        #   用 0.0 当默认值会让"显式传 0"和"没传"无法区分（见下方 __init__ 注释）。
        emotion_intensity: Optional[float] = None,
        source: str = "auto",
        consolidation_level: int = 2,
        strength: float = 60.0,
        ttl: int = 86400,
        chunk_priority: int = 5,
        category: str = "",
        importance: Optional[float] = None,
        later_thought: Optional[list] = None,
        last_mentioned_at: Optional[float] = None,
        mention_count: int = 0,
        mention_history: Optional[list] = None,
        context: Optional[dict] = None,
        decay_slowdown: float = 1.0,
        # 2026-11-08 信任度（T06）：可信度 0~1，**不随时间衰减**。
        #   ⚠️ 必须写在 __init__ 的参数列表里：from_dict 靠 hasattr 恢复字段，
        #   没声明的字段每次从磁盘重读都会被静默丢掉。
        #   None = 按内容推断（infer_credibility），显式传 0.0 也保留（不能用 truthiness 判断）。
        credibility: Optional[float] = None,
        # ===== 2026-11-08 情景档 =====
        # ⚠️ 以下字段**必须**写在 __init__ 的参数列表里。
        #   from_dict 是靠 hasattr(item, k) 恢复字段的，不在 __init__ 里声明的字段
        #   每次从磁盘重读都会被静默丢掉（decay_slowdown 就是这么死了两天的）。
        #
        # 短期记忆侧：这条碎片被哪个情景档吃掉了
        episode_id: Optional[str] = None,
        episode_at: Optional[float] = None,
        # 情景档侧
        session_id: Optional[str] = None,       # 属于哪个会话（私聊/群聊口径不能混）
        content_source: str = "original",       # "original" | "generated"（防记忆污染）
        content_confidence: str = "high",       # "high" | "medium" | "low"
        scene: Optional[dict] = None,           # when/date/turn_count/theme/theme_kind/who
        source_turns: Optional[list] = None,    # 原文 mem_id 列表（可回溯 + 去重依据）
        # ★ 2026-11-15 加：工具结果记忆的结构化字段。
        #
        #   ⚠️ 必须写在 __init__ 参数列表里 —— from_dict 靠 hasattr 恢复字段，
        #      不在这里声明的字段每次从磁盘重读都会被静默丢掉。
        #      （credit / decay_slowdown 都因为漏声明死过。）
        #
        #   结构（对应需求文档的"建议字段"）：
        #     {
        #       "operation_id": "...",     # 稳定唯一，防重放
        #       "tool": "file_download",     # 工具名
        #       "action": "文件下载",       # 人能理解的操作
        #       "status": "succeeded",     # succeeded/failed/pending/unknown
        #       "result": "文件已下载",     # 简短可核实的结果
        #       "artifact": "D:/x.mp4",    # 产物路径/标识，没有则空
        #       "error": "403"             # 失败原因，没有则空
        #     }
        #   空 dict = 不是工具结果记忆。
        tool_result: Optional[dict] = None,
        embed_status: str = "ok",               # "ok" | "pending" | "failed"
        # ★ 2026-11-09 P0（审计指出）：create_time 原来写死 now()，无法注入。
        #
        #   后果：新条目 create_time 恒等于「全池最新」，
        #   而短期淘汰按 create_time 保留最新 N 条 →
        #   新条目**永远不会被淘汰** → capacity_evicted 分支不可达。
        #
        #   审计实测：容量 3 连写 8 条，reason 全是 created，
        #   capacity_evicted 从未出现。
        #
        #   现在允许显式传入（默认 None = 用 now()，行为不变）。
        #   这让「新记忆比池内更旧」这个场景能被真实构造出来，
        #   淘汰路径也就可测了。
        create_time: Optional[float] = None,
        # ═══════════════════════════════════════════════════════════
        # 双轨衰减（2026-11-10 第二步）
        # ═══════════════════════════════════════════════════════════
        # ⚠️ 这五个字段**必须**写在 __init__ 的参数列表里。
        #   from_dict 靠 `hasattr(item, k)` 恢复字段，没在这声明的字段
        #   每次从磁盘重读都会被静默丢弃 —— decay_slowdown 就这样死过两天。
        #   tests/test_impression_decay.py::T6 专门守这条。
        #
        # 【为什么不能复用 emotion_intensity 当「当时的情绪」】
        #   memory_manager.py:74 有一条铁律：
        #     content / emotion_valence / emotion_intensity = 「当时」，写死，谁都不许改
        #   而 R4 要求情绪随时间衰减。二者直接冲突。
        #   解法不是改旧字段语义（那会让现有 372 条数据和 _emotion_match_score
        #   全部变味），而是**新开字段**把两个语义分开：
        #
        #     event_intensity     当时有多强烈   冻结，永不改
        #     current_intensity   现在还剩多少   按 emotion_at 衰减
        #     emotion_intensity   保持原样 = 当时的强度（向后兼容的别名）
        #
        #   为什么不让 emotion_intensity 原地衰减（产品方 2026-11-10 明确否决）：
        #     它只有被读时才结算，没人结算就是陈旧快照 ——
        #     三个月后召回读到的还是 70 分，跟 S04「落盘的是陈旧派生值」同一个坑。
        #
        # 【印象层】
        #   impression_strength  核心印象留存 0~100，极慢衰减
        #   impression_at        印象的结算游标（与 strength_at / emotion_at 独立）
        #
        #   ⚠️ 三个游标必须独立。S01 的根因就是 last_active 一个字段
        #     同时当「最后被想起」和「结算游标」，两种语义打架 → 全库衰减失效。
        event_intensity: Optional[float] = None,     # 当时的情绪强度（冻结）
        current_intensity: Optional[float] = None,   # 现在的情绪余温（会衰减）
        impression_strength: Optional[float] = None, # 核心印象 0~100（None = 按门槛自动决定）
        impression_at: Optional[float] = None,       # 印象结算游标
        emotion_at: Optional[float] = None,          # 情绪余温结算游标
        # 活跃资格与归档状态（2026-11-10 归档重设计）。
        # 必须显式声明：from_dict 只恢复 __init__ 已声明的字段。
        last_recalled_at: Optional[float] = None,    # 最后一次真实召回/提及
        archived_at: Optional[float] = None,         # 进入冷存时间
        archive_reason: Optional[str] = None,        # 归档原因，如 inactive_180d
        awakened_at: Optional[float] = None,         # 最近一次唤醒时间
        # ===== 2026-11-12 永久记忆（保留权与主动召回权分离）=====
        # permanent_memory  必须保留：不进冷库、不当噪音删
        # recall_weight     主动召回权重，可降到 0；与保存权无关
        # recall_mode       active 正常参与 / on_demand 仅按需检索
        # recall_count      被“实际采用”的次数（不是被检索次数）
        # last_recalled_at 由真实采用推进，检索不改它
        permanent_memory: bool = False,
        recall_weight: float = 1.0,
        recall_mode: str = "active",
        recall_count: int = 0,
        # 2026-11-13：召回门控标签。默认为空 = 还没打过，召回时按 yes 处理，
        #   保证历史数据不被误排除；打过之后才真正生效。
        recallable: str = "",
        type_tagged_by: str = "",
        # 内容分类（7 类），**与 category 分开**——category 还背着
        kind: str = "",
        #
        # 为什么单独开这些字段，不复用 category / 全局常量：
        #     再多一个维度会互相覆盖（实测踩过：改 classify 会打掉隐私标记）
        #   · 衰减速率和地板目前是 decay_logic 里的**全局常量**，
        #
        # is_private：明确隔离标记。替代 category="private" 那种隐式写法。
        # decay_rate / strength_floor：None = 用全局默认，设了才覆盖。
        # out_turns：蒸馏结论专用 —— 指向原始记录，保证结论可追溯。
        is_private: bool = False,
        decay_rate: Optional[float] = None,
        strength_floor: Optional[float] = None,
        decay_rate_mode: str = "base",
        out_turns: Optional[list] = None,
        source_kind: str = '',
        speaker: str = '',
        source_message_id: str = '',
        attachment_index=None,
        effective_from: Optional[float] = None,
        effective_to: Optional[float] = None,
    ):
        # ★ 2026-11-03 修：原来只用毫秒时间戳做 ID，同毫秒创建的记忆全部撞号
        #   （实测 166 条里 148 条共用 mem_1793278780301）。
        #   现在加 4 位随机后缀，撞号概率降到可忽略。
        self.mem_id = f"mem_{int(datetime.now().timestamp() * 1000)}_{uuid.uuid4().hex[:4]}"
        self.content = content
        self.mem_type = mem_type
        self.tags = tags or []
        # ★ 2026-11-10 第一步：情绪推断接入（与生产 schema.py 逐字一致）。
        #
        #   原来 emotion_valence / emotion_intensity 只有默认值，
        #   没有任何写入者 → 生产库 369/372 条是 neutral / 0.0。
        #
        #   后果：decay_logic.emotion_decay_factor 配好的
        #   「强情绪 → 衰减慢 2.5 倍」从来没被触发过。
        #
        #   现在：调用方**显式传**了就用，没传（None）就按内容推断。
        #
        #   ⚠️ 关键：`emotion_intensity` 的签名默认值必须改成 None。
        #      第一版写的是 `emotion_intensity: float = 0.0`，然后判断
        #      `if emotion_valence == "neutral" and (emotion_intensity or 0) == 0`
        #      —— 实测踩坑：显式传 `emotion_intensity=0.0` 时
        #      valence 是默认 neutral、intensity 是 0.0，条件成立 →
        #      **被误判成「没传」而触发推断**，结果传 0 变成了 90。
        #
        #      这正是本文件里 importance / credibility 注释反复警告的
        #      「0.0 是合法值，不能用 truthiness 判断」那个坑。
        #      根治办法：默认值用 None 表达「未传」，0.0 表达「显式无情绪」。
        # ★★★ 2026-11-10 独立审查抓出的语义错误（问题 9）★★★
        #
        #   原逻辑只看「强度传没传」，不看「极性传没传」：
        #       if emotion_intensity is None:    ← 只判这一个
        #           全部按内容推断（valence 被无条件覆盖）
        #
        #   实测：
        #     MemoryItem('今天吃了碗面', emotion_valence='negative')
        #       → emotion_valence='neutral'   ← 调用方传的 negative 被扔掉
        #     MemoryItem('他家人住院了', emotion_valence='positive')
        #       → emotion_valence='negative'  ← 用户明说 positive，被判 negative
        #
        #   「显式指定极性、只省略强度」是最自然的调用方式
        #   （valence='negative' 但不想指定 0~100 的数），
        #   这条路以前会静默把极性翻掉。
        #
        #   修法：**极性也参与判断**。
        #     · 强度和极性都没传（None + "neutral"）→ 全推断
        #     · 只传了极性（intensity=None 但 valence != "neutral"）
        #         → 保留极性，强度按该极性给一个默认档
        #     · 只传了强度 → 保留强度，极性按内容推断
        #     · 两个都传 → 都用
        #
        #   ⚠️ 注意 `emotion_valence` 的默认值是 "neutral"，
        #      所以「没传极性」和「显式传 neutral」无法区分 ——
        #      这是既有签名决定的，无法根治（除非把默认值也改成 None）。
        #      折中：把 "neutral" 当作「没传」处理，与改动前行为一致。
        _valence_given = (emotion_valence != "neutral")
        if emotion_intensity is None and not _valence_given:
            # 两个都没给 → 全推断
            _v, _i = infer_emotion(content, source)
            self.emotion_valence = _v
            self.emotion_intensity = _i
        elif emotion_intensity is None:
            # 只给了极性 → 保留极性，强度**仍按内容推断**
            #
            # ★★★ 2026-11-10 独立审查抓出的魔数（问题 B）★★★
            #
            #   上一版写的是：
            #       self.emotion_valence = emotion_valence
            #       self.emotion_intensity = 55.0      # ← 凭空的常量
            #
            #   实测后果：
            #     他家人去世了   显式only=55  纯推断=95   差 +40
            #     他今天买了瓶水 显式only=55  纯推断=0    差 -55
            #
            #   调用方传 `valence='negative'` 的本意是
            #   「我知道这是负面，强度你看着办」，
            #   而 55 变成了「不管内容是什么一律 55」。
            #
            #   而且注释写的理由是「低于建印象层门槛 60，但不为 0」——
            #   **这是在用一个魔数绕过印象层门槛，而不是表达语义。**
            #
            #   修法：极性用调用方的，强度仍推断。
            #     他家人去世了 + valence=negative → negative/95  ✅
            #     他今天买了瓶水 + valence=negative → negative/0  ✅
            #
            #   ⚠️ 行为变更：显式只传极性的调用方，强度会从固定 55
            #      变成「按内容推断」。如果内容无情绪词 → 0。
            #      这是正确的：「他今天买了瓶水」标成 negative 也不该有强度。
            _v, _i = infer_emotion(content, source)
            self.emotion_valence = emotion_valence
            self.emotion_intensity = _i
        else:
            # 给了强度（含 0.0）→ 用传入值
            #   极性：传了就用、没传（neutral）按内容推断
            try:
                self.emotion_intensity = min(100.0, max(0.0,
                                                       float(emotion_intensity)))
            except (TypeError, ValueError):
                self.emotion_intensity = 0.0
            if _valence_given:
                self.emotion_valence = emotion_valence
            else:
                # 只给强度没给极性 → 极性按内容推断，但强度保留
                _v, _ = infer_emotion(content, source)
                self.emotion_valence = (_v if self.emotion_intensity > 0
                                        else "neutral")
        # ═══════════════════════════════════════════════════════════
        # 双轨衰减初始化（2026-11-10 第二步）
        # ═══════════════════════════════════════════════════════════
        # event_intensity = 「当时有多强烈」，从 emotion_intensity 冻结一份。
        #   调用方可以显式给（覆盖推断），但**之后任何路径都不许再改它**。
        #   ⚠️ 用 is None 判断，不能用 truthiness —— 0.0 是合法的「当时没情绪」。
        if event_intensity is None:
            self.event_intensity = float(self.emotion_intensity or 0.0)
        else:
            try:
                self.event_intensity = min(100.0, max(0.0, float(event_intensity)))
            except (TypeError, ValueError):
                self.event_intensity = float(self.emotion_intensity or 0.0)

        # current_intensity = 「现在还剩多少余温」。刚建立时 = 当时。
        if current_intensity is None:
            self.current_intensity = float(self.event_intensity)
        else:
            try:
                self.current_intensity = min(100.0, max(0.0, float(current_intensity)))
            except (TypeError, ValueError):
                self.current_intensity = float(self.event_intensity)

        # 印象层：只有 event_intensity ≥ 门槛才建。
        #   ★ 任务书 7.2 风险 2：如果所有带情绪的日常对话都建印象层，
        #     库会只涨不降。所以门槛卡在 ≥60。
        #   ★ 任务书 7.2 风险 3：迁移时默认 0（见 migrate_impression.py）。
        if impression_strength is None:
            if self.event_intensity >= IMPRESSION_BUILD_MIN_INTENSITY:
                self.impression_strength = float(self.event_intensity)
            else:
                self.impression_strength = 0.0
        else:
            try:
                self.impression_strength = min(100.0, max(0.0, float(impression_strength)))
            except (TypeError, ValueError):
                self.impression_strength = 0.0

        # 三个结算游标：初值都取 create_time，之后各自独立推进。
        #   ⚠️ create_time 在下面才赋值，所以这里自己先算一遍基准，
        #     不能依赖 self.create_time 已存在（第一次就是这么炸的）。
        _ct = (float(create_time) if create_time is not None
               else datetime.now().timestamp())
        self.emotion_at = (float(emotion_at) if emotion_at is not None else _ct)
        self.impression_at = (float(impression_at) if impression_at is not None else _ct)
        self.source = source
        # ★ 2026-11-09 P0：允许注入 create_time（默认 None = now()）
        #   审计指出：写死 now() 导致「新条目比池内更旧」不可构造，
        #   短期淘汰的 capacity_evicted 分支因此不可达。
        self.create_time = (float(create_time) if create_time is not None
                            else datetime.now().timestamp())
        self.last_active = self.create_time
        # 独立的强度结算锚点；旧数据迁移时回退到 last_active。
        self.strength_at = self.create_time
        # last_recalled_at 只由真实提及/召回/唤醒推进；每日衰减巡检绝不刷新。
        self.last_recalled_at = (float(last_recalled_at)
                                 if last_recalled_at is not None else self.last_active)
        self.archived_at = float(archived_at) if archived_at is not None else None
        self.archive_reason = archive_reason
        self.awakened_at = float(awakened_at) if awakened_at is not None else None
        # 兼容前从字段里没声明的旧值由 from_dict 的 setattr 覆盖；
        # 这里先给安全默认，避免构造函数抛错。
        self.permanent_memory = bool(permanent_memory)
        try:
            self.recall_weight = min(1.0, max(0.0, float(recall_weight)))
        except (TypeError, ValueError):
            self.recall_weight = 1.0
        self.recall_mode = str(recall_mode or "active")
        if self.recall_mode not in ("active", "on_demand"):
            self.recall_mode = "active"
        try:
            self.recall_count = max(0, int(recall_count or 0))
        except (TypeError, ValueError):
            self.recall_count = 0
        # 召回门控：空字符串 = 还没打过标签
        self.recallable = str(recallable or "")
        if self.recallable and self.recallable not in ("yes", "meta_only", "no"):
            self.recallable = ""
        self.type_tagged_by = str(type_tagged_by or "")
        # kind：7 类内容分类，空 = 未打标
        self.kind = str(kind or "")
        if self.kind and self.kind not in KINDS:
            self.kind = ""

        self.is_private = bool(is_private) or (category == "private")
        # None = 用全局默认；设了才算覆盖
        self.decay_rate = None if decay_rate is None else max(0.0, float(decay_rate))
        self.decay_rate_mode = decay_rate_mode if decay_rate_mode in ("base", "effective") else "base"
        self.strength_floor = (None if strength_floor is None
                               else max(0.0, min(100.0, float(strength_floor))))
        self.out_turns = list(out_turns) if out_turns else []
        self.strength = min(100.0, max(0.0, strength))
        self.consolidation_level = consolidation_level
        self.ttl = ttl
        self.chunk_priority = chunk_priority
        self.category = category or classify_importance(content, source)[0]
        # 2026-11-04 v3：重要度（0~1，永不衰减）。不传就按内容推断。
        # 2026-11-04 v3：importance 转换加兜底。
        #   · 传入非法字符串('abc')时 float() 会抛异常 → 回退到内容推断
        #   · 传入 0.0 是合法值，必须保留（不能用 truthiness 判断）
        if importance is None:
            self.importance = infer_importance(content, source)
        else:
            try:
                self.importance = min(1.0, max(0.0, float(importance)))
            except (TypeError, ValueError):
                self.importance = infer_importance(content, source)

        # 2026-11-11 修（本体 bug）：stable_profile 保底。
        #
        #   根因：legacy_migration 迁「记忆.md」时只设 category="stable_profile"，
        #   没设 importance → 这里走 infer_importance(content, source)，
        #   只看内容形态不看 category → 「我发消息一句话接一个表情包」
        #   被判 speech(0.22)、地板 13 → 约 139 天后归档 → 她忘了自己的行为规范。
        #
        #   stable_profile = 她的稳定人格设定，本应高重要度。
        #   保底 0.55（about_him 档，地板 33）—— 既不误判成寒暄，也不过度到 fact。
        if self.category == "stable_profile":
            self.importance = max(self.importance, 0.55)
        # 2026-11-06 感受分层：「当时感受」= emotion_valence/emotion_intensity（写死不动）；
        # 「后来再想」= later_thought（list），以后可追加，不改原始 content。
        self.later_thought = later_thought if later_thought is not None else []
        # 2026-11-06 短期记忆层：最后被提起时间（驱动衰减的关键字段）
        self.last_mentioned_at = last_mentioned_at if last_mentioned_at is not None else self.create_time
        self.mention_count = mention_count
        self.mention_history = mention_history if mention_history is not None else []
        # 2026-11-08 加：衰减减速系数（被想起次数越多、衰减越慢）。
        #   必须在这里声明 —— 否则 from_dict 的 hasattr 检查会把它丢掉，
        #   导致每次从磁盘重读后都重置成默认值（跟 later_thought 同一类坑）。
        self.decay_slowdown = float(decay_slowdown) if decay_slowdown is not None else 1.0
        # 2026-11-08 信任度：跟 importance 同一套兜底写法 ——
        #   · 不传（None）→ 按内容措辞推断（好像/听说 会给低分）
        #   · 传了非法值（'abc'）→ 回退到推断，不抛异常
        #   · 传了 0.0 是合法值，必须保留（不能用 truthiness 判断）
        if credibility is None:
            self.credibility = infer_credibility(source, content)
        else:
            try:
                self.credibility = min(1.0, max(0.0, float(credibility)))
            except (TypeError, ValueError):
                self.credibility = infer_credibility(source, content)
        # 2026-11-06 场景化：context 存这轮的「情绪/话题/地点/人物」等场景元信息，
        # 让记忆从「干梗」变成「带场景的梗概」，接下去聊才有东西说。
        self.context = context if context is not None else {}
        self.embedding = []
        # ===== 2026-11-08 情景档 =====
        # 短期记忆侧：聚合后打标（标记，不删除 —— 删了就回溯不到原文）
        self.episode_id = episode_id
        self.episode_at = episode_at
        # 情景档侧
        self.session_id = session_id
        # ⚠️ content 是「生成的」还是「原文」必须标清楚：
        #   不标 → 她把自己归纳的一段当成真发生过 = 记忆污染；
        #   标了 → 注入时能说「我归纳的」，用户能纠正。
        self.content_source = content_source
        self.content_confidence = content_confidence
        self.scene = scene if scene is not None else {}
        self.source_turns = source_turns if source_turns is not None else []
        # ★ 2026-11-15 加：工具结果记忆的结构化字段。
        #
        #   为什么单独一个 dict、不塞进 content 字符串：
        #     需求要求「operation_id / tool / action / status / result /
        #     artifact / error」是独立字段，可以按 status 过滤、
        #     按 artifact 查产物；全塞进 content 就只能全文搜。
        #
        #   为什么不复用 context / scene：
        #     · scene 已被情景档占用（when/date/duration_min/theme/...）
        #     · context 是通用名，容易被别的写入方借用
        #     · 独立字段语义清晰，且 to_dict/from_dict 会自动带上
        #
        #   空 dict = 不是工具结果记忆（普通对话记忆全是空），不占空间。
        self.tool_result = tool_result if tool_result is not None else {}
        # embedding 失败也要能存（ollama 挂了不能阻断聚合），
        # 用 embed_status 记「没算出来」，之后补算
        self.embed_status = embed_status
        # Evidence metadata must survive cache round trips and legacy writers.
        self.status = 'active'
        self.deleted = False
        self.recall_excluded = False
        self.corrected_by = None
        self.superseded_by = None
        self.corrects = None
        self.corrected_at = None
        self.correction_reason = None
        from services.evidence_semantics import annotate, timestamp as _parse_ts
        self.effective_from = _parse_ts(effective_from) if effective_from is not None else None
        self.effective_to = _parse_ts(effective_to) if effective_to is not None else None
        self.subject = None
        self.predicate = None
        self.distill_status = None
        self.source_kind = source_kind
        self.speaker = speaker
        self.source_message_id = source_message_id
        self.attachment_index = attachment_index
        self.event_time = None
        self.user_confirmed = False
        self.classification_history = []
        self.qq_memory = {}  # 大肥鱼：显式主体、共享范围与来源，随跨池存取保留。
        self.evidence_metadata = annotate(self.to_dict())


    def to_dict(self) -> dict:
        return self.__dict__.copy()

    @classmethod
    def from_dict(cls, data: dict) -> "MemoryItem":
        item = cls(data.get("content", ""))
        for k, v in data.items():
            if hasattr(item, k):
                setattr(item, k, v)
        # ★ 2026-11-09 修（独立审计抓出的真 bug）：上面的 setattr **绕过了
        #   __init__ 里的全部类型/范围校验**。__init__ 有
        #   `min(100.0, max(0.0, strength))` 和 try/except 兜底，但 from_dict
        #   走的是 hasattr + setattr，等于把校验全跳过了。
        #
        #   实测（修前）：
        #     strength=None      → from_dict 后 = None      ← 保留
        #     strength='abc'     → from_dict 后 = 'abc'     ← 保留
        #     strength=9999      → from_dict 后 = 9999      ← 越界不钳
        #     mention_count='many' → = 'many'              ← 保留
        #
        #   后果：recall_engine 的 `temp_mem.strength / 100.0` 和排序
        #   `key=lambda m: m.strength` 会直接 TypeError —— **一条脏数据
        #   能让整次召回崩**，而召回是每轮都跑的热路径。
        #
        #   修法：setattr 之后统一做一次归一化。原则是「宁可修好也不炸」：
        #     非法值 → 回退默认值（不丢这条记忆，只丢那个坏字段）
        #     越界值 → 钳制到合法区间
        #   注意：`0.0` 是合法值，不能用 truthiness 判断（见下方 importance 注释）。
        item._normalize_numeric_fields()
        if not str(getattr(item, "category", "") or "").strip():
            item.category = classify_importance(item.content, item.source)[0]
        # cls(content) 会把缺失字段初始化成 now。磁盘没有该字段时，必须按
        # 数据里已有的 create_time 回退，不能把当前时间误当成历史活动时间。
        _created = getattr(item, "create_time", None)
        if data.get("last_active") is None:
            item.last_active = _created
        if data.get("last_mentioned_at") is None:
            item.last_mentioned_at = _created
        # 迁移旧记录：旧版本没有独立结算锚点，保守沿用旧 last_active。
        if data.get("strength_at") is None:
            item.strength_at = (getattr(item, "last_active", None)
                                or getattr(item, "create_time", None))
        # 旧记录没有独立召回游标时沿用 last_active，不用 strength_at：
        # 后者会被每日结算推进，不能代表用户是否还在提及这条记忆。
        if ("last_recalled_at" not in data
                or getattr(item, "last_recalled_at", None) is None):
            item.last_recalled_at = (getattr(item, "last_active", None)
                                     or getattr(item, "create_time", None))
        # 2026-11-04 v3：旧数据没有 importance 时，按内容补推断。
        # 注意：必须用 `is None` 判断，不能用 truthiness —— importance=0.0 是合法值，
        #       用 `if not` 会把它误判成「没设置」而错误重算。
        if getattr(item, "importance", None) is None:
            item.importance = infer_importance(data.get("content", ""), data.get("source", ""))
        if item.category in ("speech", "about_him", "tool", "misc"):
            inferred_category, inferred_importance = classify_importance(item.content, item.source)
            if inferred_category == "persona":
                item.category = "stable_profile"
                item.importance = max(item.importance, inferred_importance)
        # 2026-11-11（二修）：stable_profile 保底必须【无条件】执行。
        #
        #   上一版把它放在 `if importance is None` 分支内，结果不生效 ——
        #   因为磁盘里那 28 条的 importance 是写死的 0.22/0.35（不是 None），
        #   走不到那个分支。这里挪出来，无论 importance 来自推断还是磁盘，
        #   只要 category 是 stable_profile，一律保底 0.55。
        if getattr(item, "category", "") == "stable_profile":
            try:
                item.importance = max(float(item.importance or 0.0), 0.55)
            except (TypeError, ValueError):
                item.importance = 0.55
        # ★ 2026-11-10 独立审查（问题 11）：情绪也补推断，跟 importance /
        #   credibility 保持一致。
        #
        #   为什么之前没有这段：`_NUM_FIELDS["emotion_intensity"]` 的默认值
        #   曾是 0.0，所以 None 永远到不了这里。现在默认值改成 None 了，
        #   这条路径才真正可用。
        #
        #   ⚠️ 行为变更：**旧数据（磁盘上 emotion_intensity 缺失或为 null）
        #      会在加载时被推断出情绪值**。
        #
        #      这是有意的 —— 否则「历史数据不会回填」就永远是事实。
        #      但要注意影响：
        #        · 372 条里约 30 条会被推断出 >0 的强度
        #        · 其中 >= 60 的会建印象层（如果第二步的 impression 逻辑接上）
        #        · 如果不想回填，在 data 里显式给 emotion_intensity=0.0 即可
        if getattr(item, "emotion_intensity", None) is None:
            _v, _i = infer_emotion(
                data.get("content", ""), data.get("source", ""))
            item.emotion_intensity = _i
            # 极性：只有磁盘上也没有明确极性时才一起补
            if str(data.get("emotion_valence") or "neutral") == "neutral":
                item.emotion_valence = _v
        # 2026-11-06 场景化：旧数据没有 context 时补空 dict
        if getattr(item, "context", None) is None:
            item.context = {}
        # 2026-11-08 信任度：旧数据（215 条）没有 credibility，按内容补推断。
        # 注意同样用 "is None" 判断 —— 0.2（已被推翻）是合法值，不能被重算成 1.0。
        if getattr(item, "credibility", None) is None:
            item.credibility = infer_credibility(
                data.get("source", ""), data.get("content", ""))
        # ═══════════════════════════════════════════════════════════
        # 2026-11-10 第二步：旧数据迁移（T7）
        # ═══════════════════════════════════════════════════════════
        # ⚠️ 判定条件必须同时看「data 里有没有这个键」和「值是不是 None」。
        #
        #   ★ 这是第一版写错、被 T7 抓出来的真 bug：
        #     第一版只写 `if getattr(item, "impression_at", None) is None`。
        #     但 `cls(content)` 这个构造函数已经把游标初始化成 **now()** 了，
        #     所以属性永远不是 None → 迁移段永远不生效。
        #     而 setattr 循环只覆盖磁盘上**确实存在**的键 ——
        #     旧记录根本没有 impression_at 这个键，
        #     于是旧条目加载后游标停在 now()。
        #
        #     后果跟 S01 完全一样：等于给 372 条记忆集体「续命」一次
        #     （从今天起重新开始衰减）。这正是这段注释一开始想防的事。
        #
        #   同理 event_intensity：构造时按 content 推断（往往是 0），
        #   而磁盘上的 emotion_intensity=80 是 setattr 之后才写进去的，
        #   于是「从当时继承」变成「继承了个 0」。
        #
        #   修法：`"键" not in data` 也算「需要迁移」——
        #     磁盘上根本没有这个键 = 旧记录，必须按迁移规则补。
        if ("event_intensity" not in data
                or getattr(item, "event_intensity", None) is None):
            # 「当时」= 旧字段 emotion_intensity（那一份本来就是写死的历史值）
            try:
                item.event_intensity = float(
                    getattr(item, "emotion_intensity", 0.0) or 0.0)
            except (TypeError, ValueError):
                item.event_intensity = 0.0
        if ("current_intensity" not in data
                or getattr(item, "current_intensity", None) is None):
            # 余温从「当时」继续，此后由 emotion_at 驱动衰减
            item.current_intensity = float(item.event_intensity)
        if ("impression_strength" not in data
                or getattr(item, "impression_strength", None) is None):
            # ★ 任务书 7.2 风险 3：迁移**默认 0**，不许一次性造出 372 条"永久记忆"。
            #   真正需要回填的走 migrate_impression.py（显式、可回滚）。
            item.impression_strength = 0.0
        # 三个游标：缺失时回退到「这条记忆本来就在衰减」的那个锚点。
        #   用 strength_at 而不是 now()：否则旧条目会「从今天起重新开始衰减」，
        #   等于把它们全部续命一次（S01 那次就是这么把 204 条 last_active 刷新的）。
        _anchor = (getattr(item, "strength_at", None)
                   or getattr(item, "last_active", None)
                   or getattr(item, "create_time", None))
        if ("impression_at" not in data
                or getattr(item, "impression_at", None) is None):
            item.impression_at = _anchor
        if ("emotion_at" not in data
                or getattr(item, "emotion_at", None) is None):
            item.emotion_at = _anchor
        from services.evidence_semantics import annotate
        item.evidence_metadata = annotate(item.to_dict())
        return item

    # 数值字段 → (下限, 上限, 默认值)；None 表示不限
    _NUM_FIELDS = {
        "strength":          (0.0, 100.0, 60.0),
        "importance":        (0.0, 1.0, None),      # None 默认 = 按内容推断
        "credibility":       (0.0, 1.0, None),
        # ★ 2026-11-10 独立审查（问题 11）：默认值从 0.0 改成 None。
        #
        #   原来这里是 0.0，导致 from_dict 里「缺失就补推断」那条路
        #   **永远走不到**（因为 None 被 _normalize 压成 0.0 了）。
        #
        #   实测两种输入结果相反：
        #     缺 emotion_intensity 字段  → 90.0  （触发推断）
        #     emotion_intensity = None   → 0.0   （被压成 0）
        #   同一份磁盘数据，少一个字段和字段为 null 得到相反结果。
        #
        #   而同一文件里 importance / credibility 的默认值是 None，
        #   所以它们能正常回填 —— 只有 emotion 不能。
        #   这就是我此前说「历史数据不会回填」的真实原因：
        #   **不是没做回填，是这套机制让回填不可能发生。**
        "emotion_intensity": (0.0, 100.0, None),
        "decay_slowdown":    (1.0, 4.0, 1.0),
        "mention_count":     (0, None, 0),
        # ── 2026-11-10 第二步：双轨字段 ──
        # ⚠️ 默认值是 None 的两个（event_intensity / current_intensity）走
        #   「继续保留 None，交给 from_dict 的迁移段补」，不在这里瞎猜。
        "event_intensity":      (0.0, 100.0, None),
        "current_intensity":    (0.0, 100.0, None),
        "impression_strength":  (0.0, 100.0, 0.0),
        # 2026-11-12 永久记忆：召回权重独立于强度，可降到 0。
        "recall_weight":        (0.0, 1.0, 1.0),
        "recall_count":         (0, None, 0),
    }
    # 时间戳字段：必须是有限正数，否则 None（调用方会用 create_time / now 兜底）
    _TS_FIELDS = ("create_time", "last_active", "strength_at", "last_mentioned_at",
                  "episode_at", "last_recalled_at", "archived_at", "awakened_at",
                  # 2026-11-10 第二步：两个新结算游标 + 一个冻结时间
                  "impression_at", "emotion_at", "event_at")
    #   ★ event_at 只是登记（哪个时刻的 event_intensity），本版不参与结算。
    #     留着是因为「印象地板按当时的强度算」这句断言，将来可能需要审计。

    def _normalize_numeric_fields(self) -> None:
        """把从磁盘读回来的数值字段归一化（非法 → 默认，越界 → 钳制）。

        为什么需要：from_dict 用 setattr 恢复字段，绕过了 __init__ 的校验。
        为什么不能直接抛异常：磁盘上已经存在的数据不能因为一条脏行
        就让整个库加载失败 —— 那等于全库不可用。
        """
        import math as _math

        for name, (lo, hi, default) in self._NUM_FIELDS.items():
            if not hasattr(self, name):
                continue
            raw = getattr(self, name)
            # 整数语义的字段
            is_int = name in ("mention_count", "recall_count")
            if raw is None:
                if default is None:
                    continue
                setattr(self, name, default if not is_int else int(default))
                continue
            try:
                val = float(raw)
            except (TypeError, ValueError):
                if default is None:
                    setattr(self, name, None)
                else:
                    setattr(self, name, default if not is_int else int(default))
                continue
            # NaN / inf 也不能留（NaN 参与比较永远是 False，会让排序静默错乱）
            if not _math.isfinite(val):
                if default is None:
                    setattr(self, name, None)
                else:
                    setattr(self, name, default if not is_int else int(default))
                continue
            if lo is not None and val < lo:
                val = lo
            if hi is not None and val > hi:
                val = hi
            setattr(self, name, int(val) if is_int else val)

        # consolidation_level：只能是 1/2/3（DECAY_RATE_MAP 只认这三个键）
        if hasattr(self, "consolidation_level"):
            try:
                lvl = int(self.consolidation_level)
            except (TypeError, ValueError):
                lvl = 2
            if lvl not in (1, 2, 3):
                lvl = 2
            self.consolidation_level = lvl

        # 2026-11-13：recallable 枚举校验。
        #
        #   为什么必须放在这里而不是 __init__：
        #   from_dict 走的是 hasattr + setattr，会**绕过 __init__ 的全部校验**
        #   （同文件上方已有同类注释）。只写在 __init__ 里的话，
        #   盘上一旦出现脏值就会被原样读回，门控逻辑再拿它比较就会出错。
        if hasattr(self, "recallable"):
            _r = str(getattr(self, "recallable", "") or "")
            self.recallable = _r if _r in ("yes", "meta_only", "no") else ""

        # 2026-11-13：kind 也要在 from_dict 后校验（同上，setattr 绕过 __init__）
        if hasattr(self, "kind"):
            _k = str(getattr(self, "kind", "") or "")
            self.kind = _k if _k in KINDS else ""

        self.is_private = bool(getattr(self, "is_private", False)) or (
            str(getattr(self, "category", "") or "") == "private")
        _dr = getattr(self, "decay_rate", None)
        self.decay_rate_mode = (getattr(self, "decay_rate_mode", "base")
                                if getattr(self, "decay_rate_mode", "base") in ("base", "effective") else "base")
        if _dr is not None:
            try:
                self.decay_rate = max(0.0, float(_dr))
            except (TypeError, ValueError):
                self.decay_rate = None
        _sf = getattr(self, "strength_floor", None)
        if _sf is not None:
            try:
                self.strength_floor = max(0.0, min(100.0, float(_sf)))
            except (TypeError, ValueError):
                self.strength_floor = None
        if not isinstance(getattr(self, "out_turns", None), list):
            self.out_turns = []

        # 时间戳：非有限数 → None（让调用方走各自的兜底链）
        for name in self._TS_FIELDS:
            if not hasattr(self, name):
                continue
            raw = getattr(self, name)
            if raw is None:
                continue
            try:
                val = float(raw)
            except (TypeError, ValueError):
                setattr(self, name, None)
                continue
            if not _math.isfinite(val) or val <= 0:
                setattr(self, name, None)
                continue
            setattr(self, name, val)
